L3_1 = {}
L3_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 5700101
L3_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "JUDGE_CHARADE_NPC_NULL"
L3_1.m_Talk_KOREA = "이상, 중요 참고인들의 증언을 바탕으로……."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "以上、重要参考人の証言をもとに……"
L3_1.m_Talk_ENG = "In the light of the testimony provided by material witnesses..."
L3_1.m_Talk_TWN = "以上，根據幾位重要證人的證詞……"
L3_1.m_Talk_THA = "จากคำให้การของพยาน..."
L3_1.m_Talk_VTN = "Dựa trên lời khai được cung cấp bởi các nhân chứng quan trọng..."
L3_1.m_Talk_SCN = "综合以上重要相关证人的证词……"
L3_1.m_Talk_DEU = "Angesichts der Aussagen wichtiger Zeugen ..."
L3_1.m_Talk_FRA = "À la lumière des témoignages fournis par les principaux témoins..."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 5700101
L4_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "JUDGE_CHARADE_NPC_NULL"
L4_1.m_Talk_KOREA = "피고의 간첩 행위 및 관리국의 핵심 기밀을 유출한 혐의가 사실로 밝혀졌습니다."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "被告のスパイ行為および管理局の核心的機密を漏洩させた疑いが事実であることが明らかになりました。"
L4_1.m_Talk_ENG = "It is evident that the defendant took part in espionage and leaked key secrets of the Administration."
L4_1.m_Talk_TWN = "認定被告涉嫌從事間諜活動及洩漏管理局重要機密的罪證屬實，"
L4_1.m_Talk_THA = "เห็นได้ชัดว่าจำเลยมีส่วนร่วมในคดีและร่วมกันเปิดเผยความลับของฝ่ายบริหาร"
L4_1.m_Talk_VTN = "Đó là bằng chứng bị cáo đã tham gia hoạt động gián điệp và làm rò rỉ những bí mật quan trọng của Cục Quản Lý."
L4_1.m_Talk_SCN = "经查实，被告涉嫌从事间谍活动并泄露了管理局核心机密。"
L4_1.m_Talk_DEU = "haben sich die Vorwürfe gegenüber der Angeklagten wegen Spionage und Weitergabe vertraulicher Informationen der Administration als wahr erwiesen."
L4_1.m_Talk_FRA = "Il est évident que les accusations d'espionnage et de divulgation des secrets de l'Administration sont irréfutables."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 5700101
L5_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "JUDGE_CHARADE_NPC_NULL"
L5_1.m_Talk_KOREA = "허나 피고는 여전히 잘못을 뉘우치지 않고, 범행을 부인하는 모습을 보이고 있습니다."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "ですが、被告はいまだに反省せず、犯行を否認する姿勢を見せています。"
L5_1.m_Talk_ENG = "However, she denies any involvement in the alleged offense and shows no remorse."
L5_1.m_Talk_TWN = "然而，被告犯後毫無悔意，並且否認犯行，"
L5_1.m_Talk_THA = "แต่เธอก็ยังให้การปฏิเสธว่าไม่มีส่วนร่วมใดๆ ในความผิดนี้ จึงไม่แสดงความสำนึกผิดใดๆ"
L5_1.m_Talk_VTN = "Tuy nhiên, cô ấy phủ nhận mọi liên quan đến hành vi phạm tội bị cáo buộc và không hề tỏ ra ăn năn."
L5_1.m_Talk_SCN = "但被告仍不悔改，且否认犯下的罪行。"
L5_1.m_Talk_DEU = "Allerdings bestreitet die Angeklagte weiterhin jegliche Beteiligung an der mutmaßlichen Straftat und zeigt keine Reue."
L5_1.m_Talk_FRA = "Cependant, l'accusée nie toute implication dans l'infraction présumée et ne montre aucun remords."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 5700101
L6_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "JUDGE_CHARADE_NPC_NULL"
L6_1.m_Talk_KOREA = "이에 따라, 본 재판부는 피고에게 종신형을 선고하는 바입니다."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "よって、本法廷は被告に終身刑を言い渡します。"
L6_1.m_Talk_ENG = "Accordingly, the court sentences the defendant to life imprisonment."
L6_1.m_Talk_TWN = "因此，當庭宣判處以被告無期徒刑。"
L6_1.m_Talk_THA = "ศาลจึงพิพากษาให้จำเลยจำคุกตลอดชีวิต"
L6_1.m_Talk_VTN = "Theo đó, tòa án tuyên phạt bị cáo mức án chung thân."
L6_1.m_Talk_SCN = "据此，本审判庭判处被告终身监禁。"
L6_1.m_Talk_DEU = "Daher verurteilt das Gericht die Angeklagte zu einer lebenslangen Haftstrafe."
L6_1.m_Talk_FRA = "En conséquence, le tribunal condamne l'accusée à la peine d'emprisonnement à perpétuité."
L7_1 = {}
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 5700101
L7_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L7_1.m_bWaitClick = false
