L8_1 = {}
L8_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 5700101
L8_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Talk_KOREA = "남자한테 눈이 멀어서 핵심 기밀을 팔아 넘기다니…. 믿기지가 않아."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "男にハマって核心的機密を売り飛ばすとは……信じられない。"
L8_1.m_Talk_ENG = "I can't believe it... She sold the Administration's secrets all for a man she barely knows."
L8_1.m_Talk_TWN = "被男人迷得團團轉洩漏出重要機密…真不敢相信。"
L8_1.m_Talk_THA = "ไม่อยากจะเชื่อเลย... ว่าเธอขายความลับของฝ่ายบริหารทั้งหมดให้กับชายที่เธอแทบจะไม่รู้จัก"
L8_1.m_Talk_VTN = "Tôi không thể tin được... Cô ấy đã bán tất cả bí mật của Cục Quản Lý cho một người đàn ông không quen biết."
L8_1.m_Talk_SCN = "居然被男人被蒙蔽了双眼，泄露核心机密……真是令人难以置信。"
L8_1.m_Talk_DEU = "Ich kann es einfach nicht glauben. Sie hat vertrauliche Informationen der Administration an einen Mann verkauft, den sie kaum kannte."
L8_1.m_Talk_FRA = "Je n'arrive pas y croire... Elle a vendu les secrets de l'Administration pour un homme qu'elle connaît à peine."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 5700101
L9_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Talk_KOREA = "그러니까요. 남편이랑 애만 딱하게 됐네요."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "本当です。旦那さんとお子さんがかわいそうですよね。"
L9_1.m_Talk_ENG = "I know. I feel sorry for her husband and daughter."
L9_1.m_Talk_TWN = "就是說啊，把老公和孩子害得這麼悽慘。"
L9_1.m_Talk_THA = "รู้สึกสงสารสามีและลูกสาวของเธอว่าไหม"
L9_1.m_Talk_VTN = "Tôi biết. Tôi thấy tiếc cho chồng và con gái của cô ấy."
L9_1.m_Talk_SCN = "是啊，可怜了她的丈夫和孩子。"
L9_1.m_Talk_DEU = "Ja, das ist wirklich unfassbar. Ihr Mann und ihre Tochter tun mir wirklich leid."
L9_1.m_Talk_FRA = "C'est clair. Je me sens désolé pour son mari et sa fille."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 5700101
L10_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Talk_KOREA = "불쌍할 게 뭐 있어? 남편도 한통속일지 누가 알아."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "何もかわいそうだなんて思う必要ないだろう？　旦那も一緒にやったのかもしれないし。"
L10_1.m_Talk_ENG = "Why do you feel sorry for them? Who knows? Maybe the husband was in on it too."
L10_1.m_Talk_TWN = "有什麼好慘的？說不定她老公和她是一夥的，誰知道？"
L10_1.m_Talk_THA = "ทำไมต้องสงสารกับพวกเขาหล่ะ? ใครจะรู้ล่ะ? บางทีสามีเขาก็มีส่วนด้วย "
L10_1.m_Talk_VTN = "Tại sao cảm thấy tiếc cho họ? Ai mà biết được? Có lẽ người chồng cũng biết thì sao."
L10_1.m_Talk_SCN = "有什么好可怜的？谁知道她丈夫是不是和她一伙的。"
L10_1.m_Talk_DEU = "Warum tun sie dir leid? Vielleicht war der Ehemann auch in die ganze Sache verwickelt."
L10_1.m_Talk_FRA = "Pourquoi vous sentez-vous désolés pour eux ? Qui sait ? Peut-être que le mari était dans le coup, lui aussi."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 5700101
L11_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Talk_KOREA = "빼앗긴 아티팩트는 이제 무슨 수로 되찾아 올 건데?"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "奪われたアーティファクトはどうやって取り戻すんだ？"
L11_1.m_Talk_ENG = "So how are they going to get back the stolen Artifact?"
L11_1.m_Talk_TWN = "現在要怎麼把被搶走的人造神器找回來？"
L11_1.m_Talk_THA = "ว่าแต่ พวกเขาจะเอาอาร์ติแฟ็กต์ที่ถูกขโมยไป กลับคืนมาได้ไง?"
L11_1.m_Talk_VTN = "Vậy họ sẽ lấy lại Thần Khí bị đánh cắp bằng cách nào?"
L11_1.m_Talk_SCN = "被抢走的人造神器要怎么找回来啊？"
L11_1.m_Talk_DEU = "Wie wollen sie bloß das gestohlene Artefakt zurückbekommen?"
L11_1.m_Talk_FRA = "Alors, comment vont-ils récupérer l'artefact volé ?"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 5700101
L12_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Talk_KOREA = "사라졌다는 <color=#ffd34c>콜드 케이스</color>라는 게…… 그렇게 중요한 물건인가요?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "消えた<color=#ffd34c>コールドケース</color>って……そんなに大事な物なんですか？"
L12_1.m_Talk_ENG = "The missing <color=#ffd34c>Cold Case</color>... Is it that important?"
L12_1.m_Talk_TWN = "那個不見的<color=#ffd34c>Cold Case</color>……是很重要的東西嗎？"
L12_1.m_Talk_THA = "แล้ว<color=#ffd34c>โคลด์เคส</color> ที่หายไป... มันสำคัญขนาดนั้นเลยเหรอ?"
L12_1.m_Talk_VTN = "<color=#ffd34c>Cold Case</color> bị mất tích ấy... Nó có quan trọng không?"
L12_1.m_Talk_SCN = "那个消失的叫<color=#ffd34c>诡异神器</color>的东西……就那么重要吗？"
L12_1.m_Talk_DEU = "Der verschwundene <color=#ffd34c>Cold Case</color> ... Ist er denn wirklich so wichtig?"
L12_1.m_Talk_FRA = "Cette <color=#ffd34c>Affaire classée</color>... Est-elle si importante ?"
L13_1 = {}
L13_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 5700101
L13_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Talk_KOREA = "……쉿. 멍청아. 기밀 사항이라고. 목소리 낮춰."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "……しっ。バカ。機密事項なんだ。声を抑えろ。"
L13_1.m_Talk_ENG = "...Shush, you idiot. Keep your voice down! It's top secret."
L13_1.m_Talk_TWN = "……噓！你這笨蛋，這可是機密，小聲一點！"
L13_1.m_Talk_THA = "...ชู่ว์ อย่าเสียงดังสิ ! นั่นไม่ใช่สิ่งจะมาพูดตรงนี้มันเป็นความลับน่ะ"
L13_1.m_Talk_VTN = "...Suỵt, đồ ngốc. Nói bé thôi! Đó là bí mật."
L13_1.m_Talk_SCN = "……嘘，你个蠢货，都说了是机密，给我小点声。"
L13_1.m_Talk_DEU = "... Pssst! Du Idiot. Sprich nicht so laut! Das ist streng geheim."
L13_1.m_Talk_FRA = "Chut, idiot... Parle moins fort ! C'est top secret."
