L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 5700101
L16_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "FELICETTE_CANARY_NULL_QM"
L16_1.m_Talk_KOREA = "믿고 있었는데……."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "信じてたのに……"
L16_1.m_Talk_ENG = "I trusted you..."
L16_1.m_Talk_TWN = "我那麼相信你……"
L16_1.m_Talk_THA = "ฉันเชื่อใจคุณ..."
L16_1.m_Talk_VTN = "Cháu đã tin tưởng ngài..."
L16_1.m_Talk_SCN = "我这么相信你……"
L16_1.m_Talk_DEU = "Ich habe Ihnen vertraut ..."
L16_1.m_Talk_FRA = "Je vous faisais confiance..."
