L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_BGCrash = 30
L17_1.m_fBGCrashTime = 0.5
L17_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_04"
L17_1.m_CharStrID = "FELICETTE_CANARY_NULL_QM"
L17_1.m_Talk_KOREA = "솔직하게 말하면, 엄마랑 아빠가 감옥에 가지 않게 도와줄 거라고 했으면서!"
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "正直に話したら、ママとパパが刑務所に行かないようにしてくれるって言ったのに！"
L17_1.m_Talk_ENG = "You said that if I told the truth, that you would help Mommy and Daddy not go to jail!"
L17_1.m_Talk_TWN = "是你說不會讓爸爸媽媽進去坐牢的！"
L17_1.m_Talk_THA = "เธอบอกว่าหากฉันบอกความจริงเธอจะช่วยพ่อกับแม่ไม่ให้ติดคุก!"
L17_1.m_Talk_VTN = "Ngài nói nếu cháu nói thật thì ngài sẽ giúp bố mẹ cháu không phải vào tù!"
L17_1.m_Talk_SCN = "你明明说过会帮忙，不会让我爸爸妈妈进监狱的！"
L17_1.m_Talk_DEU = "Sie meinten, wenn ich die Wahrheit sage, würden Sie Mama und Papa helfen, nicht ins Gefängnis zu gehen!"
L17_1.m_Talk_FRA = "Vous avez dit que si je disais la vérité, vous aideriez maman et papa à échapper à la prison !"
L18_1 = {}
L18_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 5700101
L18_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "FELICETTE_CANARY_NULL_QM"
L18_1.m_Talk_KOREA = "이럴 줄 알았으면…… 아무것도 말하지 말 걸……."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "こうなるとわかってたら……何も言わなかった……"
L18_1.m_Talk_ENG = "If I knew this was going to happen... I would've kept my mouth shut..."
L18_1.m_Talk_TWN = "早知道會這樣……我一句話都不會說……"
L18_1.m_Talk_THA = "ถ้าฉันรู้ว่ามันจะเป็นแบบนี้... ฉันก็คงจะไม่ให้คำอะไรเลย..."
L18_1.m_Talk_VTN = "Nếu biết thế này thì... Cháu sẽ ngậm miệng lại..."
L18_1.m_Talk_SCN = "早知道会这样……我就什么都不说了……"
L18_1.m_Talk_DEU = "Wenn ich gewusst hätte, dass das passieren würde ... hätte ich einfach den Mund gehalten ..."
L18_1.m_Talk_FRA = "Si j'avais su que ça finirait comme ça... j'aurais gardé le silence..."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 5700101
L19_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "FELICETTE_CANARY_NULL_QM"
L19_1.m_Talk_KOREA = "나 때문에, 나 때문에 엄마, 아빠가……."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "私のせいで、私のせいでママとパパが……"
L19_1.m_Talk_ENG = "It's all because of me... that Mommy and Daddy are..."
L19_1.m_Talk_TWN = "都是我害的，都是我，害爸爸媽媽……"
L19_1.m_Talk_THA = "ทั้งหมดมันเป็นเพราะฉัน...ที่ทำให้พ่อและแม่ต้องเป็นแบบนี้..."
L19_1.m_Talk_VTN = "Tất cả là tại con... mà bố mẹ mới..."
L19_1.m_Talk_SCN = "都是因为我，因为我爸爸妈妈才会……"
L19_1.m_Talk_DEU = "Es ist alles nur meinetwegen, dass Mama und Papa ..."
L19_1.m_Talk_FRA = "C'est à cause de moi... que maman et papa sont..."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 5700101
L20_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Talk_KOREA = "무슨 착각을 하는 거니, 루이즈?"
L20_1.m_fTalkTime = 0.03
L20_1.m_bTalkCenterFadeIn = true
L20_1.m_Talk_JPN = "何を勘違いしてるのかしら？　ルイーズ。"
L20_1.m_Talk_ENG = "What are you talking about, Louisé?"
L20_1.m_Talk_TWN = "你是不是哪裡有誤會，露易絲？"
L20_1.m_Talk_THA = "เธอกำลังพูดบ้าอะไร?"
L20_1.m_Talk_VTN = "Nhóc đang nói gì vậy,  Louisé?"
L20_1.m_Talk_SCN = "你是不是搞错了，路易斯小朋友？"
L20_1.m_Talk_DEU = "Wovon redest du, Louise?"
L20_1.m_Talk_FRA = "De quoi parles-tu, Louise ?"
L21_1 = {}
L21_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 5700101
L21_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Talk_KOREA = "네가 본 걸 숨겨 봤자, 너희 부모님이 저지른 죄가 없던 걸로 되는 건 아니잖아."
L21_1.m_fTalkTime = 0.03
L21_1.m_bTalkCenterFadeIn = true
L21_1.m_Talk_JPN = "あなたが見たことを隠しても、あなたの両親の犯した罪がなかったことにはならないわ。"
L21_1.m_Talk_ENG = "Even if you hide the truth, it doesn't make the crimes your parents committed go away."
L21_1.m_Talk_TWN = "就算你不說你看到什麼，也不表示你父母就是無罪的。"
L21_1.m_Talk_THA = "ถึงเธอจะเก็บซ่อนความจริงเอาไว้ แต่ก็ไม่ได้หมายความว่าสิ่งที่พ่อและแม่ของเธอก่อไว้จะลบมันได้"
L21_1.m_Talk_VTN = "Dù có che giấu sự thật thì cũng không làm cho tội ác mà cha mẹ nhóc gây ra biến mất được"
L21_1.m_Talk_SCN = "就算你不说出你看到的东西，你父母犯下的罪也不会消失。"
L21_1.m_Talk_DEU = "Selbst wenn du verheimlichst, was du gesehen hast, heißt das nicht, dass deine Eltern das Verbrechen nicht begangen haben."
L21_1.m_Talk_FRA = "Même si tu essaies de cacher la vérité, ça ne fera pas disparaître les crimes que tes parents ont commis."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "CHARADE2_ACT1_PROLOGUE@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 5700101
L22_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Talk_KOREA = "나도 안타깝지만, 죄 지은 사람은 그에 합당한 벌을 받아야지."
L22_1.m_fTalkTime = 0.03
L22_1.m_bTalkCenterFadeIn = true
L22_1.m_Talk_JPN = "私も残念だと思うけど、罪を犯した人はそれ相応の罰を受けないとね。"
L22_1.m_Talk_ENG = "It's a shame, but bad people must be punished for what they did."
L22_1.m_Talk_TWN = "我也覺得很遺憾，但犯罪的人就該受到應有的懲罰。"
L22_1.m_Talk_THA = "น่าเสียดายเนาะ แต่ยังไงคนไม่ดีก็ต้องถูกลงโทษในสิ่งที่พวกเขาทำไว้"
L22_1.m_Talk_VTN = "Thật đáng xấu hổ nhưng kẻ xấu phải bị trừng phạt vì tội lỗi của mình."
L22_1.m_Talk_SCN = "我也觉得很遗憾，但既然犯了错，就该受到应有的惩罚。"
L22_1.m_Talk_DEU = "Es tut mir ja auch leid, aber diejenigen, die ein Verbrechen begehen, müssen angemessen bestraft werden."
L22_1.m_Talk_FRA = "C'est regrettable, mais les mauvaises personnes doivent être punies pour ce qu'elles ont fait."
