L32_1 = "이런 빈민가에 지부를 내다니……."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "こんなスラム街に支部を出すとは……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Creating a branch in a slum like this..."
L31_1.m_Talk_ENG = L32_1
L32_1 = "竟然把分公司設在貧民區……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "บริษัทมาสร้างสาขาในสลัมแบบนี้ได้ไง..."
L31_1.m_Talk_THA = L32_1
L32_1 = "Xây chi nhánh ở một khu ổ chuột như thế này..."
L31_1.m_Talk_VTN = L32_1
L32_1 = "居然在这种贫民窟开分公司……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "In so einem Slum eine Zweigstelle zu eröffnen ..."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Quelle idée de créer une annexe dans un bidonville comme celui-ci..."
L31_1.m_Talk_FRA = L32_1
