L33_1 = "m_CharScaleTime"
L32_1[L33_1] = 0.01
L33_1 = "오는 길이 꽤나 험했어, 최고 관리자. 강도 미수만 세 번은 겪었으니까."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ここに来るまでの道はかなり危険なものだったよ、最高管理者。強盗未遂だけでも3回はあったからな。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "It was quite the trip, Supreme Administrator. I almost got mugged three times on my way over here."
L32_1.m_Talk_ENG = L33_1
L33_1 = "來的路上很驚險欸，最高管理者。光是搶奪未遂就遇到三次吧？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "นี่เป็นการเดินทางที่ไกล ของผู้บริหารสูงสุด  ฉันเกือบถูกปล้นตั้งสามครั้งระหว่างที่เดินทางมาที่นี่"
L32_1.m_Talk_THA = L33_1
L33_1 = "Chuyến đi quả là tuyệt vời, Quản Trị Viên Tối Cao. Tôi suýt bị cướp ba lần trên đường tới đây đấy."
L32_1.m_Talk_VTN = L33_1
L33_1 = "一路上真是历尽艰辛，最高管理者。光是抢劫未遂，就已经经历三次了。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Es war ein harter Weg, Oberster Administrator. Auf dem Weg hierher wurde ich dreimal fast überfallen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Quel voyage éreintant, Administrateur suprême. J'ai failli me faire agresser trois fois sur le chemin."
L32_1.m_Talk_FRA = L33_1
