L34_1 = "m_CharScaleTime"
L33_1[L34_1] = 0.01
L34_1 = "뭐, 그건 마음씨 넓은 내가 이해해주도록 할까?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "まあ、それは心の広い私が理解してやってもいい。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "But having a heart of gold, I guess I should be understanding, right?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "不過誰叫我人美心善良，我就大人不記小人過吧？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "สงสัยพวกนั้นคงคิดว่า หัวใจฉันเป็นทองล่ะมั้ง ว่าไหม?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nhưng với đức tính nhân hậu, chắc là tôi nên thông cảm nhỉ?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "算了，心胸宽广的我就理解一下吧。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Aber da ich ein Herz aus Gold habe, sollte ich bestimmt Verständnis dafür haben, nicht wahr?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mais ayant un cœur en or, je suppose que je devrais essayer de les comprendre, non ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
