L34_1[L35_1] = L36_1
L35_1 = "그래서 마음씨 넓으신 손님께서 여기 어쩐 일인가?"
L34_1.m_Talk_KOREA = L35_1
L35_1 = "それで、心の広いお客さんがここに何の用だ？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "So, what brings Ms. Heart-of-gold here?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "所以這位人美心善良的小姐，請問你來這裡有何貴幹？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "แล้วอะไรทำให้ มิสหัวใจสีทองหอบมาที่นี่?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Vậy điều gì đã mang cô Nhân Hậu đến đây?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "所以，心胸宽广的这位客人，来这里有何贵干？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Also, was bringt meinen Gast mit einem „Herz aus Gold“ hierher?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Alors, qu'est-ce qui t'amène ici, mademoiselle Cœur-en-or ?"
L34_1.m_Talk_FRA = L35_1
