L36_1 = "우린 지금 코핀 컴퍼니에서 압수한 자료들을 분석중이야."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "私たちは今コフィンカンパニーから押収した資料を分析しているところだ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "We're analyzing the property we seized from Coffin Company."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我們正在分析從科芬公司扣押的資料。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เรามาเพื่อคำนวณทรัพย์สินที่เรายึดมาจากบริษัทคอนฟิน"
L35_1.m_Talk_THA = L36_1
L36_1 = "Chúng tôi đang phân tích tài sản được tịch thu từ Công ty Coffin."
L35_1.m_Talk_VTN = L36_1
L36_1 = "我们正在分析从科芬公司没收的资料。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wir analysieren gerade die Ausrüstung, die wir von Coffin Company beschlagnahmt haben."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Nous sommes en train d'analyser la propriété de la Compagnie Coffin que nous avons saisie."
