L36_1[L37_1] = 0.01
L37_1 = "솔직히 순조롭지는 않아. 애초에 파손된 장비들이 대부분이기도 하고."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "正直順調ではない。そもそもほとんどの装備が破損していてな。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "To be honest, it's not going so well. I mean, most of them were broken equipment after all."
L36_1.m_Talk_ENG = L37_1
L37_1 = "老實說不太順利，因為大部分是原本就壞掉的裝備。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "พูดตามตรงนะ มันไม่ได้ราบรื่นอย่างที่เราคิด ฉันหมายถึงว่าส่วนใหญ่แล้ว ที่ได้มาคืออุปกรณ์ที่พังทั้งหมด"
L36_1.m_Talk_THA = L37_1
L37_1 = "Thành thật mà nói thì không được suôn sẻ cho lắm. Ý tôi là hầu hết chúng đều bị hỏng."
L36_1.m_Talk_VTN = L37_1
L37_1 = "说实话并不是很顺利，因为从一开始大部分装备都是破损的。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ehrlich gesagt, läuft es nicht so glatt. Ich meine, der Großteil der Ausrüstung war bereits beschädigt."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Pour être honnête, ça ne se passe pas aussi bien que prévu. La plupart des équipements trouvés étaient en morceaux."
L36_1.m_Talk_FRA = L37_1
