L40_1 = "m_CharScaleTime"
L39_1[L40_1] = 0.01
L40_1 = "흥, 시치미 떼지 마. 처음부터 우리에게 순순히 기술을 넘길 생각이 없던 거겠지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "フン、しらばっくれるな。最初から素直に技術を渡すつもりなどなかったんだろう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Hmph, don't play dumb with me. You were never going to just hand over your technology to us, were you?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "哼，少在那邊裝蒜，你根本打從一開始就不打算乖乖地把技術交出來吧？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ฮึ่ม อย่ามาล้อฉันสิ คุณจะไม่มอบเทคโนโลยีของคุณให้กับเราใช่ไหม?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Hừm, đừng có giả ngốc với tôi. Ngài sẽ không bao giờ giao công nghệ của mình cho chúng tôi phải không?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "哼，可别装蒜了。你当初就没想过要把技术乖乖地交给我们吧。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Hmpf, stell dich nicht dumm. Wahrscheinlich hattest du von Anfang an nicht die Absicht, uns eure Technologie zu übergeben."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Hmph ! Ne joue pas l'idiot avec moi. Tu n'avais nullement l'intention de nous remettre ta technologie, n'est-ce pas ?"
