L41_1 = "m_CharScale"
L42_1 = {}
L43_1 = 1.2
L44_1 = 1.2
L42_1[1] = L43_1
L42_1[2] = L44_1
L40_1[L41_1] = L42_1
L41_1 = "m_CharScaleTime"
L40_1[L41_1] = 0.01
L41_1 = "우리도 바보는 아니야. 기술 격차라는 건 언젠가 반드시 따라잡히기 마련이지."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "私たちもバカではない。技術の差というものは、いつかは埋まるものだ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "We're not that oblivious. It's only a matter of time before we catch up to your technology."
L40_1.m_Talk_ENG = L41_1
L41_1 = "不過我們也不是笨蛋，我們總有一天會追上這樣的技術落差的。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เรายังไม่ลืมขนาดนะ อีกไม่นานเราก็จะยึดเทคโนโลยีของคุณมา"
L40_1.m_Talk_THA = L41_1
L41_1 = "Chúng tôi không bị bỏ quên thế đâu. Chỉ là vấn đề thời gian trước khi chúng tôi bắt kịp công nghệ của ngài,"
L40_1.m_Talk_VTN = L41_1
L41_1 = "我们也不傻，技术上的差距总有一天是能追上的。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Aber unterschätze uns nicht. Es ist nur eine Frage der Zeit, bis wir mit eurer Technologie Schritt halten werden."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Nous ne sommes pas si stupides. Ce n'est qu'une question de temps avant que nous parvenions à rattraper ton niveau de technologie."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
