L42_1 = "m_Crash"
L41_1[L42_1] = 10
L42_1 = "하지만, 작전 현장에서 배포된 <color=#ffd34c>얼터니움 리액터</color>……."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "だが、作戦現場で配布された<color=#ffd34c>オルタニウムリアクター</color>……"
L41_1.m_Talk_JPN = L42_1
L42_1 = "However, the <color=#ffd34c>Alternium Reactor</color> that was distributed at the operation..."
L41_1.m_Talk_ENG = L42_1
L42_1 = "但是我問你，作戰現場的<color=#ffd34c>黑化永恆之金電抗器</color>……"
L41_1.m_Talk_TWN = L42_1
L42_1 = "แต่ยังไง <color=#ffd34c>เครื่องปฏิกรณ์อัลเทอร์เนียม</color> ที่ถูกกระจายในปฏิบัติการ..."
L41_1.m_Talk_THA = L42_1
L42_1 = "Tuy nhiên, <color=#ffd34c>Lò Phản Ứng Vàng Thay Thế</color> mà được phân phối tại chiến dịch..."
L41_1.m_Talk_VTN = L42_1
L42_1 = "但是，在之前作战中分发的那个<color=#ffd34c>黑化能晶反应堆</color>……"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Aber dieser <color=#ffd34c>Alternium-Reaktor</color>, der bei der Operation verteilt wurde ..."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Cependant, le <color=#ffd34c>réacteur à alternium</color> qui a été remis lors de l'opération..."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
