L43_1 = "m_CharScaleTime"
L42_1[L43_1] = 0.01
L43_1 = "대체 그건 뭐지? 신기술이라고 얼버무릴 생각은 하지 마."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "あれはいったい何なんだ？　新技術といって誤魔化そうとするな。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "What is that? And don't try to gloss over it saying it's new technology."
L42_1.m_Talk_ENG = L43_1
L43_1 = "那到底是什麼？是新技術嗎？少跟我打哈哈喔！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "มันคืออะไรกัน? และซ่อนมันแล้วบอกว่าเป็นเทคโนโลยีใหม่นะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Đó là cái gì? Đừng cố che đậy rằng đó là công nghệ mới."
L42_1.m_Talk_VTN = L43_1
L43_1 = "到底是什么东西？你可别想搪塞我说，那只是个新技术。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Was ist das überhaupt für ein Ding? Und versuche ja nicht, dich rauszureden und zu sagen, dass es sich einfach um irgendeine neue Technologie handelt."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Qu'est-il réellement ? Et n'essaie pas d'esquiver la question en disant qu'il s'agit d'une nouvelle technologie."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
