L44_1 = "m_Crash"
L43_1[L44_1] = 20
L44_1 = "아무런 대가도 없이, 그렇게 막대한 출력을 제공하는 물건이 세상에 존재할 리 없잖아."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "何の代償もなく、あれほど膨大な出力を出せるものがこの世に存在するわけないだろう？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "There's no way anything with that massive output at no cost can exist in this world."
L43_1.m_Talk_ENG = L44_1
L44_1 = "世界上怎麼可能有不需要付任何代價，就可以提供如此龐大輸出的東西！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ไม่มีอะไรจะได้มาฟรีๆ ในโลกนี้"
L43_1.m_Talk_THA = L44_1
L44_1 = "Không đời nào thứ có đầu ra khổng lồ đó mà không mất phí gì lại có thể tồn tại trên thế giới này."
L43_1.m_Talk_VTN = L44_1
L44_1 = "没有任何代价就能提供如此巨大的功率，世界上怎么可能会有这种东西。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Es ist unmöglich, dass irgendetwas mit dieser riesigen Ausgabe einfach so auf dieser Welt existieren kann."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Dans ce monde, il est impossible qu'un objet puisse produire une telle quantité d'énergie sans en payer le prix."
L43_1.m_Talk_FRA = L44_1
