L48_1 = "USER_ADMIN_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "아니. 자네 말대로라네."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "いや。君の言うとおりさ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Yes, you are right."
L47_1.m_Talk_ENG = L48_1
L48_1 = "沒錯，正如你所說的。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ใช่ ถูกต้องแล้ว"
L47_1.m_Talk_THA = L48_1
L48_1 = "Đúng, cô nói đúng."
L47_1.m_Talk_VTN = L48_1
L48_1 = "没错，正如你所说。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ja, du hast recht."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Oui, tu as raison."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "CHARADE2_ACT1_PROLOGUE@48#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5700101
L48_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "USER_ADMIN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "이 세상에 대가가 없는 일이 어디 있겠나?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "この世に代償のいらないものなどない。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Everything in this world must pay a price, no?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "天下沒有白吃的午餐。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ทุกสิ่งในโลกนี้ต้องแลกมาด้วยเงินว่าไหม?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Mọi thứ trên đời này đều phải trả giá phải không?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "世上哪会有免费的午餐呢？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Alles auf dieser Welt hat einen Preis, nicht wahr?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Tout a un prix dans ce monde, n'est-ce pas ?"
L48_1.m_Talk_FRA = L49_1
