L50_1[L51_1] = L52_1
L51_1 = "GROUND_ADMIN_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "m_Pos"
L52_1 = "C"
L50_1[L51_1] = L52_1
L51_1 = "……뭐, 좋아. 어차피 단서가 없는 건 아니니까."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "……まあ、いい。手がかりがないわけでもないからな。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "...Well, all right. It's not like we don't have a lead or anything."
L50_1.m_Talk_ENG = L51_1
L51_1 = "……很好，反正我們也有掌握一些線索。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "...งั้นก็เอาหล่ะ ไม่ใช่ว่าเราจะไม่มีเบาะแสอะไรเลย"
L50_1.m_Talk_THA = L51_1
L51_1 = "...Chà, được thôi. Không phải là bọn tôi không có manh mối hay gì."
L50_1.m_Talk_VTN = L51_1
L51_1 = "……好吧，反正又不是没有线索。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "... Nun gut. Es ist ja nicht so, dass wir keinen Anhaltspunkt oder so hätten."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Bon, très bien... Ce n'est pas comme si nous n'avions pas de piste ou quoi..."
L50_1.m_Talk_FRA = L51_1
