L1_1[L2_1] = L3_1
L2_1 = "당신 회사의 거래 내역을 추적해 봤더니, 폐기 판정 받은 이터니움을 꾸준히 매입해왔더군."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "あなたの会社の取引内容を追跡してみたが、廃棄されたエタニウムの買い取りを恒常的に行ってきたようだな。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "We traced back your company's transaction history and found that you kept buying Eternium marked for disposal."
L1_1.m_Talk_ENG = L2_1
L2_1 = "我們追蹤你們公司的交易紀錄，發現你們一直有在買進廢棄處理的永恆之金。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "เราตรวจสอบเส้นทางการเงินของบริษัทของคุณ และพบว่าคุณยังคงซื้ออีเทอร์เนียมที่มีเครื่องหมายเพื่อนำไปกำจัด"
L1_1.m_Talk_THA = L2_1
L2_1 = "Chúng tôi đã truy lại lịch sử giao dịch của công ty ngài và tìm được ngài liên tục mua Vàng Vĩnh Cửu được đánh dấu vứt bỏ."
L1_1.m_Talk_VTN = L2_1
L2_1 = "我查了一下你们公司的交易明细，发现你们一直在采购废弃的能晶。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Wir haben den Transaktionsverlauf deines Unternehmens zurückverfolgt und festgestellt, dass du weiterhin Eternium gekauft hast, das eigentlich entsorgt werden sollte."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Nous avons retracé l'historique des transactions de ton entreprise et avons constaté que tu as régulièrement acheté de l'éternium destiné à être jeté."
L1_1.m_Talk_FRA = L2_1
