L5_1 = "C"
L3_1[L4_1] = L5_1
L4_1 = "그 폐기 판정을 받은 이터니움을 특수한 방법으로 가공한 무언가겠지. 안 그래?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "その廃棄されたエタニウムを、特殊な方法で加工した何かだろう。違うか？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "made by processing the Eternium marked for disposal in a special way, right?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "應該就是將廢棄處理的永恆之金以特殊方法加工後的產物，我說的沒錯吧？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "การประมวลผลอีเทอร์เนียมที่ทำเครื่องหมายไว้เพื่อการกำจัดด้วยวิธีพิเศษใช่ไหม?"
L3_1.m_Talk_THA = L4_1
L4_1 = "được tạo ra bằng cách xử lý Vàng Vĩnh Cửu được đánh dấu tiêu hủy theo cách đặc biệt, phải không?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "用特殊方法加工废弃能晶后得到的某个东西，不是吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "durch die Verarbeitung von zu entsorgendem Eternium mithilfe eines besonderen Verfahrens hergestellt, oder?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Fabriqué en traitant l'éternium obsolète avec une technique spéciale, c'est bien ça ?"
