L6_1 = "USER_ADMIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "혼자서 거기까지 알아내다니 대단하군."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "一人でそこまで突き止めるとは、流石だな。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I'm impressed you figured that out all on your own."
L5_1.m_Talk_ENG = L6_1
L6_1 = "竟然可以靠自己找到這些資料，蠻厲害的。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ผมประทับใจคุณจริงๆที่คิดทั้งหมดนี่ได้ด้วยตัวเอง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ấn tượng lắm."
L5_1.m_Talk_VTN = L6_1
L6_1 = "你自己能调查到那个程度，确实了不起。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich bin beeindruckt, dass du das ganz alleine herausgefunden hast."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Je suis impressionné, tu as compris tout ça par toi-même."
