L7_1 = "USER_ADMIN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "하지만 알려줄 수는 없네. 다른 사람에게 권할 만큼 안전한 방법이 아니야."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "だが、教えてやるわけにはいかない。他人にお勧めできるほど安全な方法ではないのでね。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "But I cannot go into detail. Just know that it is not safe enough to be recommended to others."
L6_1.m_Talk_ENG = L7_1
L7_1 = "不過恕我無可奉告，畢竟這不是適合推薦給別人的好方法。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "แต่ผมไม่สามารถบอกละเอียดได้ เพราะมันไม่ปลอดภัยที่จะไปบอกให้ผู้อื่นทราบ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Nhưng tôi không thể nói chi tiết. Chỉ biết là nó không đủ an toàn để giới thiệu cho người khác."
L6_1.m_Talk_VTN = L7_1
L7_1 = "但我只能说无可奉告，毕竟这个方法并没有安全到可以推荐给别人。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Aber ich kann es dir nicht im Detail erklären. Das Verfahren ist nämlich noch nicht ausgereift genug, um sie anderen zu empfehlen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Mais je ne peux pas entrer dans les détails. Cette technique n'est pas assez sûre pour être divulguée à d'autres personnes."
L6_1.m_Talk_FRA = L7_1
