L8_1 = "흥, 나도 시니어이기 이전에 학자야."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "フン、私もシニアである前に学者だ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Hmph. You know, I may be a Senior, but I am a scholar too."
L7_1.m_Talk_ENG = L8_1
L8_1 = "哼，我在當Senior之前可是位學者好嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ฮึ่ม คุณรู้ไหมว่าฉันอาจเป็นผู้อาวุโส แต่ฉันก็เป็นนักวิชาการเหมือนกัน"
L7_1.m_Talk_THA = L8_1
L8_1 = "Hừm. Ngài biết đấy, tôi có thể là một Thành Viên Cấp Cao, nhưng tôi cũng là một học giả."
L7_1.m_Talk_VTN = L8_1
