L9_1 = "m_Crash"
L8_1[L9_1] = 15
L9_1 = "어디 그렇게 계속 감춰 보시지. 필요하다면 어떻게 해서든 알아낼 테니까."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "そうやってずっと隠してみろ。必要ならどんな手を使ってでも突き止めてやる。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Let's see how well you keep this from me. But if needed, I will find out what it is one way or another."
L8_1.m_Talk_ENG = L9_1
L9_1 = "你就盡管藏著不說吧，必要的話我會想辦法找出答案的！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แล้วมาดูกันว่าคุณจะเก็บเรื่องนี้กับฉันได้ดีแค่ไหน แต่ถ้าจำเป็นฉันจะหาว่ามันคืออะไร ไม่ทางใดก็ทางหนึ่ง"
L8_1.m_Talk_THA = L9_1
L9_1 = "Để xem ngài giữ kín chuyện này đến mức nào nhé. Nhưng nếu cần, kiểu gì tôi cũng sẽ tìm ra thôi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "你有本事就继续藏着吧。如果有必要，我会想尽办法查出来的。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Mal sehen, ob du es schaffst, es weiterhin vor mir zu verheimlichen. Wenn nötig, werde ich schon irgendwie auf die eine oder andere Weise herausfinden, was genau es ist."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Voyons jusqu'à quand tu réussiras à me cacher ton petit secret. Je découvrirai bien de quoi il s'agit d'une manière ou d'une autre, si j'en ai besoin."
L8_1.m_Talk_FRA = L9_1
