L11_1.m_CharStrID = L12_1
L12_1 = "그래서, 근황을 알려주려고 굳이 여기까지 먼 길을 온 건가?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "それで、近況を知らせるためだけに遠路はるばる訪ねてきたのか？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "So, you came all this way just to give me a progress report?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "所以你遠道而來，只是為了通知我你的近況嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "คุณมาที่นี่เพื่อรายงานความคืบหน้าให้ฉันฟังเหรอ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Vậy cô đến tận đây chỉ để báo cáo tiến độ cho tôi sao?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "所以，你大老远跑来应该不单是为了告诉我你的近况吧？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Du bist also den ganzen Weg hierhergekommen, nur um mich über den Stand der Ermittlungen zu informieren?"
