L13_1 = "……蠻聰明的嘛。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "...เอาล่ะ ฉันจับทางคุณได้แล้ว"
L12_1.m_Talk_THA = L13_1
L13_1 = "...Chà, ngài nắm bắt nhanh đấy."
L12_1.m_Talk_VTN = L13_1
L13_1 = "……被你看出来了。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "... Du hast mich schnell durchschaut."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Tu comprends vite..."
L12_1.m_Talk_FRA = L13_1
