L13_1[L14_1] = L15_1
L14_1 = "맞아. 내가 여기 온 이유는 따로 있어."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "そうだ。私がここに来た理由は別にある。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "You're right. I'm here for a different reason."
L13_1.m_Talk_ENG = L14_1
L14_1 = "不錯，我來這裡是因為有其他的理由。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "คุณพูดถูก ฉันมาที่นี่เพราะมีเหตุผลที่แตกต่าง"
L13_1.m_Talk_THA = L14_1
L14_1 = "Đúng là tôi ở đây vì một lý do khác."
L13_1.m_Talk_VTN = L14_1
L14_1 = "没错，我来这里另有目的。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Du hast recht. Ich bin aus einem anderen Grund hier."
L13_1.m_Talk_DEU = L14_1
L14_1 = "C'est vrai. Je suis ici pour une raison différente."
L13_1.m_Talk_FRA = L14_1
