L20_1.m_CharStrID = L21_1
L21_1 = "m_Pos"
L22_1 = "L"
L20_1[L21_1] = L22_1
L21_1 = "어때, 무슨 말 하는 지 들려?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "どうだ？　何話してるのか聞こえるか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "So? Can you hear what they're talking about?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "怎麼樣？有偷聽他們在說什麼嗎？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แล้วไง? เธอได้ยินสิ่งที่พวกเขากำลังพูดไหม?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Thế nhóc nghe được họ đang nói gì không?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "怎么样，能不能听到在说什么？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Also? Kannst du hören, worüber sie reden?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Alors ? Tu entends de quoi ils parlent ?"
L20_1.m_Talk_FRA = L21_1
