L24_1 = "C"
L22_1[L23_1] = L24_1
L23_1 = "아뇨. 목소리가 너무 작게 들려서요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "いいえ。声が小さすぎて。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "No. I can't hear them very well."
L22_1.m_Talk_ENG = L23_1
L23_1 = "沒有，聲音好小，根本聽不見。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ไม่ ฉันได้ยินพวกเขาไม่ค่อยถนัด"
L22_1.m_Talk_THA = L23_1
L23_1 = "Không nghe rõ lắm."
L22_1.m_Talk_VTN = L23_1
L23_1 = "听不到，声音太小了。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Nein, sie sprechen viel zu leise."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Non, je n'entends presque rien."
