L24_1 = "m_Crash"
L23_1[L24_1] = 10
L24_1 = "그런데 이렇게 사장님이랑 손님 대화를 엿들어도 괜찮을까요?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "でも、こうやって社長とお客様の会話を盗み聞きしてもいいんでしょうか？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "But are you sure it's okay to eavesdrop on Boss's conversation with his guest?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "不過這樣偷聽老闆跟客人對話沒關係嗎？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "แต่เธอแน่ใจหรอว่าสามารถแอบฟังการสนทนาของบอสกับแขกของเขาได้อ่ะ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Nhưng cô có chắc là ổn không khi nghe lén Ông Chủ nói chuyện với khách?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "不过，这样偷听老板和客人的对话真的合适吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Aber sind Sie sicher, dass es in Ordnung ist, das Gespräch zwischen dem Boss und seinem Gast zu belauschen?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Mais vous êtes sûre qu'on a vraiment le droit d'écouter la conversation du directeur avec son invitée ?"
L23_1.m_Talk_FRA = L24_1
