L27_1 = "m_Crash"
L26_1[L27_1] = 20
L27_1 = "저게 평범한 손님 같냐, 얼빵아?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "あれは普通の客じゃないんだよ、間抜け。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "You really think she's some ordinary guest, Goon?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "你看她像普通的客人嗎，小瓜呆？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เธอคิดว่านั่นเธอเป็นแขกธรรมดาจริงๆ เหรอ?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Nhóc thực sự nghĩ cô ta là khách bình thường sao, đồ ngốc?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "那看着像普通的客人吗，你个呆瓜！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Glaubst du wirklich, dass sie nur ein gewöhnlicher Gast ist, Dummerchen?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Tu crois vraiment qu'il s'agit d'une invitée comme les autres, la crétinos ?"
L26_1.m_Talk_FRA = L27_1
