L29_1 = "L"
L27_1[L28_1] = L29_1
L28_1 = "저 여자, 코치를 만나러 여기까지 왔다면서."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "あの女、コーチに会うためにここまで来たんだろ？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "That woman came all this way to meet with Coach."
L27_1.m_Talk_ENG = L28_1
L28_1 = "那個女的是來找教練的，"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เธอคนนั้นมาที่นี่เพื่อพบกับบอส"
L27_1.m_Talk_THA = L28_1
L28_1 = "Người phụ nữ đó đã đến tận đây để gặp Huấn Luyện Viên."
L27_1.m_Talk_VTN = L28_1
L28_1 = "那个女人为了见教练大老远专程跑来这里。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Diese Frau ist den ganzen Weg hierhergekommen, um sich mit dem Trainer zu treffen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Cette femme est venue jusqu'ici pour rencontrer le coach."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
