L30_1 = "L"
L28_1[L29_1] = L30_1
L29_1 = "그럼 당연히 코치의 숨겨둔 애인 아니겠어? 이런 재밌는 상황을 놓칠 수는 없지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ってことは、当然コーチが秘密にしている彼女ってことだ。こんな面白い状況、見逃すわけにはいかないだろ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "That has to make her his hidden lover, no? I can't miss something this entertaining!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "肯定是教練藏起來的女朋友吧？這麼精彩的事怎麼能夠錯過！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "หรือว่าเธอเป็นคนรักที่บอสซ่อนอยู่ใช่ไหม? พลาดไม่ได้แล้วกับความบันเทิงขนาดนี้!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Nghĩa là cô ta là người tình giấu mặt của ổng đấy phải không? Tôi không thể bỏ lỡ điều hay ho này!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "肯定是教练偷偷发展的地下恋人啊！这么好玩的情况我又怎么能错过？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Sie muss die heimliche Geliebte des Trainers sein. So etwas Unterhaltsames darf ich mir nicht entgehen lassen!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "C'est sûrement sa maîtresse ! Je ne veux surtout pas rater quelque chose d'aussi divertissant !"
L28_1.m_Talk_FRA = L29_1
