L34_1 = "C"
L32_1[L33_1] = L34_1
L33_1 = "신경 쓰지 마세요, 노엘. 라이카 머릿속에는 원래 저런 것밖에 없으니까."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "気にしないでください、ノエル。ライカの頭の中には、もともとああいったことしか入ってないんですから。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Don't mind her, Noelle. Laika's head is always full of lewd things."
L32_1.m_Talk_ENG = L33_1
L33_1 = "別聽萊卡胡說，洛艾兒。她腦袋裡都裝那種東西。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "อย่าสนใจเธอเลย โนเอล จิตใจของไลกาเต็มไปด้วยสิ่งลามกอยู่ตลอด"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đừng bận tâm đến cô ấy, Noelle. Đầu Laika chỉ toàn chứa đầy những thứ tục tĩu."
L32_1.m_Talk_VTN = L33_1
L33_1 = "别听她胡说，诺艾尔。莱卡的脑子里向来都只有那种东西。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ignorier sie einfach, Noelle. Leica hat nichts als anzügliche Gedanken in ihrem Kopf."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ne l'écoute pas, Noelle. Leica a toujours des idées obscènes."
L32_1.m_Talk_FRA = L33_1
