L34_1 = "밖에 있는 경호원들 봤죠? 저 여자, 관리국의 고위 간부가 분명해요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "外にいるボディーガードを見ましたよね？　あの女、きっと管理局の幹部クラスです。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Didn't you see the bodyguards outside? I'm pretty sure that she's a high-ranking official of the Administration."
L33_1.m_Talk_ENG = L34_1
L34_1 = "有看到門外的保鑣嗎？那個女的一定管理局的高層。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เธอไม่เห็นบอดี้การ์ดข้างนอกนั่นเหรอ? ฉันค่อนข้างแน่ใจว่าเธอเป็นเจ้าหน้าที่ระดับสูงของฝ่ายบริหาร"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cô không thấy vệ sĩ bên ngoài à? Tôi khá chắc cô ấy là một quan chức cấp cao của Cục Quản Lý."
L33_1.m_Talk_VTN = L34_1
L34_1 = "看到外面的那些警卫了吧？那个女人肯定是管理局的高层干部。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Habt ihr die Sicherheitswächter draußen nicht gesehen? Ich bin mir ziemlich sicher, dass sie eine hochrangige Consigliere der Administration ist."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Vous avez vu les gardes du corps à l'extérieur ? Je suis à peu près sûre qu'elle est un haut fonctionnaire de l'Administration."
L33_1.m_Talk_FRA = L34_1
