L41_1 = "아무튼 코치랑 저 여자가 어떤 관계인지 꼭 알아내야 해요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "とにかく、コーチとあの女がどんな関係なのか、絶対確かめないと。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Anyway, I must figure out what their relationship is."
L40_1.m_Talk_ENG = L41_1
L41_1 = "總之一定要弄清楚教練和她的關係。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ยังไง ฉันต้องคิดให้ออกว่าความสัมพันธ์ของพวกเขาเป็นอะไรกัน"
L40_1.m_Talk_THA = L41_1
L41_1 = "Dù sao thì tôi cũng phải tìm hiểu xem mối quan hệ của họ là gì."
L40_1.m_Talk_VTN = L41_1
L41_1 = "总之，必须查清楚教练和那个女人是什么关系。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Wie auch immer, ich muss unbedingt herausfinden, was für eine Beziehung unser Trainer zu dieser Frau hat."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Quoi qu'il en soit, je dois comprendre la nature de leur relation."
L40_1.m_Talk_FRA = L41_1
