L47_1.m_CharStrID = L48_1
L48_1 = "m_Pos"
L49_1 = "C"
L47_1[L48_1] = L49_1
L48_1 = "직원 교육을 어떻게 하는 거야? 윗사람들 대화를 엿듣기나 하고."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "社員教育がなってないな。上司の話を盗み聞きするとは。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "How do you train your employees? Do they all have a habit of eavesdropping on their boss's conversations?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "你是怎麼教員工的？竟然偷聽高層談話。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "คุณอบรมพนักงานของคุณยังไง? ปล่อยให้พวกเขามีนิสัยสอดรู้สอดเห็นเรื่องของบอสจังห๊ะ?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ngài đào tạo nhân viên của mình kiểu gì vậy? Chẳng lẽ đều có thói quen nghe lén Ông Chủ nói chuyện à?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "你到底是怎么教育职员的？竟敢偷听上级对话？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Was bringst du eigentlich deinen Angestellten bei? Ist es Teil ihrer Ausbildung, die Gespräche ihres Vorgesetzten zu belauschen?!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "C'est comme ça que tu formes tes employés ? Ont-ils tous l'habitude d'écouter les conversations privées de leur directeur ?"
L47_1.m_Talk_FRA = L48_1
