L52_1 = "C"
L50_1[L51_1] = L52_1
L51_1 = "그치만 손님이 사장님을 만나려고 그라운드 원에서 여기까지 찾아왔다고 하셨잖아요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "でも、社長に会うためにグラウンド・ワンからここまで来たとおっしゃっていたじゃないですか。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "But you said you came all the way from Ground One to meet Boss."
L50_1.m_Talk_ENG = L51_1
L51_1 = "可是是你自己說你是從G1來找老闆的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "แต่คุณบอกว่าคุณเดินทางมาจากกราวด์วันเพื่อพบกับบอส"
L50_1.m_Talk_THA = L51_1
L51_1 = "Nhưng cô nói cô đã đến tận Ground One để gặp Ông Chủ."
L50_1.m_Talk_VTN = L51_1
L51_1 = "我听说您为了见老板千里迢迢从G1来这里。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Aber Sie sagten doch, Sie sind den ganzen Weg von Ground One hierhergekommen, um den Boss zu treffen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Mais vous avez dit que vous veniez du Site n°1 pour rencontrer le directeur."
L50_1.m_Talk_FRA = L51_1
