L6_1 = "그래서 혹시 손님이 저희 사장님과 특별한 사이가 아닐까 했죠!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "それで、もしかしたらお客様が社長と特別な間柄ではないかと思いまして！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "So we thought you and Boss had some kind of special relationship!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "所以當然就會想說你是不是和老闆有什麼特殊關係嘛！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เราก็เลยคิดว่าคุณกับบอสมีความสัมพันธ์พิเศษกัน!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Thế nên chúng tôi tưởng cô và Ông Chủ có mối quan hệ đặc biệt nào đó!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "所以，我就想您和我们老板会不会是什么特别的关系！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Also dachten wir, dass Sie und der Boss eine ganz besondere Beziehung zueinander hätten!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Nous avons donc pensé que vous et le directeur aviez une sorte de relation spéciale !"
L5_1.m_Talk_FRA = L6_1
