L21_1 = "경기를 앞둔 선수에게 폭력을 행사하면 어떡해요? 관리국이면 다예요?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "試合前の選手に暴力を振るうなんて。管理局だから許されるとでも思ってるんですか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "How dare you exert violence on a player right before her match? You think being in the Administration gives you that power?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "怎麼可以對快要比賽的選手施暴！！管理局了不起嗎？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "คุณกล้าใช้ความรุนแรงกับผู้เล่นก่อนการแข่งขันได้อย่างไร? คุณคิดว่าการอยู่ในฝ่ายบริหารให้อำนาจแก่คุณอย่างนั้นหรือ?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Sao cô dám dùng vũ lực với người chơi ngay trước trận đấu chứ? Cô  tưởng mình trong Cục Quản Lý có quyền đó à?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "怎么可以对马上要比赛的选手施暴！管理局了不起啊？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wie können Sie es wagen, bei einer Spielerin kurz vor dem Spiel Gewalt anzuwenden? Glauben Sie, dass Sie eine Sondergenehmigung haben, nur weil Sie für die Administration arbeiten?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Comment osez-vous attaquer un joueur juste avant son match ? Vous pensez qu'être dans l'Administration vous donne ce pouvoir ?"
