L26_1 = "꼬마야? 지금 내가 잘 못들은 것 같은데…… 다시 한 번 말해볼래?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "おチビ。今のは私の聞き間違いだと思うが……もう一度言ってくれないか？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Hey, kiddo. Could you repeat what you just said? I must have misheard?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "小鬼？我沒聽錯吧……你可以再說一次嗎？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เฮ้ เด็กๆ พวกเธอช่วยพูดอีกครังได้ไหม เมื่อกี้เธอพูดอะไรนะ? ฉันคงจะฟังผิดไปไหม..."
L25_1.m_Talk_THA = L26_1
L26_1 = "Này nhóc. Nhóc nhắc lại cái vừa nói được không? Chắc là tôi nghe nhầm..."
L25_1.m_Talk_VTN = L26_1
L26_1 = "小鬼？我好像没听清楚……你能不能再说一遍？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Hey, Kindchen. Könntest du wiederholen, was du gerade gesagt hast? Ich muss mich wohl verhört haben?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Répète ce que tu viens de dire, gamine... Je crois que j'ai mal entendu."
L25_1.m_Talk_FRA = L26_1
