L38_1 = {}
L39_1 = "CHARADE2_ACT1_PROLOGUE@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5700101
L38_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "GROUND_ADMIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "m_Pos"
L40_1 = "C"
L38_1[L39_1] = L40_1
L39_1 = "하지만 저 애도 엄청 비뚤어졌네. 샤레이드는 역시 애들 키우기 좋은 곳이 못 돼."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "しかし、あの子も相当ひねくれてるな。シャレードはやはり子育てにはいい環境じゃない。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But it seems she's become really sour. I guess it proves that Charade isn't a place to raise kids."
L38_1.m_Talk_ENG = L39_1
L39_1 = "不過那孩子怎麼變得越來越沒禮貌，查雷德果然不是個適合教養孩子的好地方。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่ดูเหมือนเธอจะซ่ามาก ฉันเดาว่ามันพิสูจน์ได้ว่าชาเรดไม่ใช่ที่สำหรับเลี้ยงลูก"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng có vẻ như cô bé đó đã trở nên rất chua chát. Điều đó chứng tỏ Charade không phải là nơi để nuôi dạy trẻ con."
L38_1.m_Talk_VTN = L39_1
L39_1 = "不过，那个孩子性格也挺扭曲的。查雷德果然不适合养孩子。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber es scheint, dass diese Göre wirklich sauer geworden ist. Charade ist definitiv kein guter Ort, um Kinder großzuziehen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais on dirait qu'elle est devenue sacrément aigrie avec le temps. Ça prouve bien que Charade n'est pas un endroit où élever des enfants."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
