L41_1 = "설마 다른 용건이라는 건, 펠리세트와 관련된 일인가?"
L40_1.m_Talk_KOREA = L41_1
L41_1 = "まさか他の用件というのは、フェリセットにまつわることなのか？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "The reason you came here, does it have something to do with Félicette?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "你說的事，跟費莉塞特有關嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เหตุผลที่คุณมาที่นี่ มันเกี่ยวอะไรกับเฟลิเซ็ตหรือเปล่า?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Lý do cô đến đây có liên quan gì đến Félicette không?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "你说的另有目的，难道是和菲利塞特有关？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Der Grund, warum du hierher gekommen bist ... Könnte es sein, dass es um Felicette geht?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "La raison pour laquelle tu es venue ici, est-ce que ça a quelque chose à voir avec Felicette ?"
