L42_1 = "뭐야, 당신? 저 아이에 대해서 뭔가 알고 도와주는 거 아니었어?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "何だ。あの子について知っていて手伝っているわけではなかったのか？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "What? Weren't you helping her out after learning about what she's been through?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "搞什麼？你什麼都不知道就聘請她嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "อะไรกัน คุณไม่ได้ช่วยสอนเธอในการเรียนรู้เกี่ยวกับสิ่งที่เธอเจอมาใช่ไหม?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cái gì? Không phải ngài giúp nó vì biết về những gì nó đã trải qua sao?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "什么啊？你帮那个孩子，不是因为知道些什么才帮的吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Was meinst du? Hast du ihr nicht geholfen, nachdem du erfahren hast, was sie durchgemacht hat?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Quoi ? Je croyais que tu t'occupais d'elle après avoir appris tout ce qu'elle avait traversé."
