L46_1 = "당신이 저 문제아를 데리고 건틀렛 리그에 출전했다는 건 이미 알고 있어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "あなたがあの問題児を連れてガントレットリーグに出戦するということは知っていた。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I already know you're participating in the Gauntlet with that delinquent child."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我知道你要派那個問題兒童參加聖鎧聯賽。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฉันรู้อยู่แล้วว่าคุณกำลังเข้าร่วมในกอนต์เล็ตกับเด็กเกเรพวกนั้น"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi đã biết ngài đang tham gia Gauntlet với đứa trẻ phạm pháp đó."
L45_1.m_Talk_VTN = L46_1
L46_1 = "我知道你带着那个问题儿童参加了圣铠联赛。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich weiß bereits, dass du mit diesem Problemkind an der Fehde-Liga teilnimmst."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Je suis déjà au courant que tu participes à la Compétition avec cette petite délinquante."
