L50_1[L51_1] = L52_1
L51_1 = "흥, 하긴 시니어들 이름도 기억 안 하는데, 그런 사소한 사건들이야 알 리가 없나."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "フン、シニアたちの名前も覚えていないし、あんな些細な事件ならなおさらか。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Hmph. You can't even remember the names of Seniors, so how would you know of a trivial case like that?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "哼，你連Senior的名字都不記得，這種小事不知道也是正常的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ฮึ่ม คุณจำชื่อของรุ่นพี่คุณได้ แล้วคุณจะรู้ได้อย่างไรเกี่ยวกับเคล็ดลับเล็กๆน้อยๆกับเธอ ?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Hừm. Tên của các Thành Viên Cấp Cao ngài cũng không nhớ được, thì làm sao biết tới một trường hợp tầm thường như cô bé đó?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "哼，也是，你连资深管理者的名字都记不得，更不会知道这种小事情了。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Hmpf. Du kannst dich ja nicht einmal an die Namen der Senioren erinnern. Warum solltest du also über einen so trivialen Fall Bescheid wissen ..."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Hmph. Tu n'arrives même pas à te souvenir du nom des Seniors, alors comment pourrais-tu être au courant d'un incident aussi trivial."
L50_1.m_Talk_FRA = L51_1
