L4_1 = "CHARADE2_ACT1_PROLOGUE@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 5700101
L3_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "GROUND_ADMIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "저 아이의 부모는 관리국 연구원이었어. 수집한 아티팩트를 관리하는 역할이었지."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "あの子の親は管理局の研究員だった。収集したアーティファクトの管理を担当していたんだ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "That child's parents were researchers at the Administration. They were tasked with managing Artifacts there."
L3_1.m_Talk_ENG = L4_1
L4_1 = "她的父母曾經是管理局的研究人員，負責管理收集來的人造神器。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "พ่อแม่ของเด็กคนนั้นเป็นนักวิจัยจากฝ่ายบริหาร พวกเขาได้รับมอบหมายให้จัดการอาร์ติแฟ็กต์ที่นั่น"
L3_1.m_Talk_THA = L4_1
L4_1 = "Cha mẹ của đứa trẻ đó là nhà nghiên cứu tại Cục Quản Lý. Họ được giao nhiệm vụ quản lý Thần Khí ở đó."
L3_1.m_Talk_VTN = L4_1
L4_1 = "她父母本是管理局的研究员，专门管理收集的人造神器。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Die Eltern dieses Kindes waren Forscher bei der Administration. Sie wurden mit der Verwaltung der dortigen Artefakte beauftragt."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Les parents de cette gamine étaient des chercheurs de l'Administration. Ils étaient chargés de s'occuper des artefacts."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "CHARADE2_ACT1_PROLOGUE@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 5700101
L4_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "GROUND_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "그런데 그 중 하나가 사라진 거야."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "だが、その中の一つが消えた。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But one of them went missing."
L4_1.m_Talk_ENG = L5_1
L5_1 = "但某一天其中一個人造神器不翼而飛。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่หนึ่งในนั้นก็หายไป"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nhưng một trong số chúng đã mất tích."
L4_1.m_Talk_VTN = L5_1
L5_1 = "但其中一个人造神器在某天消失了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Aber eines dieser Artefakte ist verschwunden."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais l'un d'eux a disparu."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "CHARADE2_ACT1_PROLOGUE@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5700101
L5_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "GROUND_ADMIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "수사 과정에서는 <color=#ffd34c>북방합의체</color>가 연루되어 있다는 사실까지 밝혀졌고."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "捜査の過程で<color=#ffd34c>北方合意体</color>が関わっているという事実が明らかになってな。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "During the investigation, it was discovered that the <color=#ffd34c>Northern Union</color> was involved."
L5_1.m_Talk_ENG = L6_1
L6_1 = "調查過程中發現，他們勾結<color=#ffd34c>北方和議會</color>。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ในระหว่างการสืบสวน พบว่า <color=#ffd34c>สหภาพฝ่ายเหนือ</color> มีส่วนเกี่ยวข้อง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Trong quá trình điều tra, người ta phát hiện ra <color=#ffd34c>Liên Minh Phía Bắc</color> có liên quan."
L5_1.m_Talk_VTN = L6_1
L6_1 = "调查期间，发现过程中还牵扯到了<color=#ffd34c>北方联盟</color>。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Im Zuge der Ermittlungen stellte sich heraus, dass die <color=#ffd34c>Nordvereinigung</color> involviert war."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Au cours de l'enquête, il a été découvert que l'<color=#ffd34c>Union du Nord</color> était impliquée."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
