L9_1 = "CHARADE2_ACT1_PROLOGUE@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 5700101
L8_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "USER_ADMIN_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "담당자들이 아티팩트를 북방합의체에 팔아넘겼다고 본 건가?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "担当者がアーティファクトを北方合意体に売り渡したと見られたのか？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Are you saying that they sold an Artifact to the Northern Union?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "他們將人造神器賣給北方和議會是嗎？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "คุณกำลังบอกว่าพวกเขาขายอาร์ติแฟ็กต์ให้กับสหภาพฝ่ายเหนือเหรอ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ý cô là họ đã bán Thần Khí cho Liên Minh Phía Bắc?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "所以负责人认为，是他们把人造神器卖给了北方联盟？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Willst du damit sagen, dass sie ein Artefakt an die Nordvereinigung verkauft haben?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Es-tu en train de dire qu'ils ont vendu un artefact à l'Union du Nord ?"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "CHARADE2_ACT1_PROLOGUE@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 5700101
L9_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "m_Face"
L11_1 = "UNIT_IDLE"
L9_1[L10_1] = L11_1
L10_1 = "GROUND_ADMIN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "m_Pos"
L11_1 = "C"
L9_1[L10_1] = L11_1
L10_1 = "그래. 하지만 북방합의체와의 관계를 증명할 수는 없는 상황이었지."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "ああ。だが、北方合意体との関係を証明することはできない状況だった。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Correct. But there was no actual way of proving their ties with the Northern Union."
L9_1.m_Talk_ENG = L10_1
L10_1 = "沒錯，但是沒有證據證明他們和北方和議會有勾結。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ถูกต้อง  แต่ไม่มีวิธีใดที่จะพิสูจน์ความสัมพันธ์ของพวกเขากับสหภาพเหนือได้อย่างแท้จริง"
L9_1.m_Talk_THA = L10_1
L10_1 = "Chính xác. Nhưng không có cách nào để chứng minh quan hệ của họ với Liên Minh Phía Bắc."
L9_1.m_Talk_VTN = L10_1
L10_1 = "没错，不过没有证据证明他们与北方联盟有关联。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Korrekt. Aber es war nicht möglich, ihre Verbindung zur Nordvereinigung nachzuweisen."
L9_1.m_Talk_DEU = L10_1
L10_1 = "En effet. Mais il n'y avait aucune preuve concrète pour prouver leurs liens avec l'Union du Nord."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "CHARADE2_ACT1_PROLOGUE@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 5700101
L10_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "m_Face"
L12_1 = "UNIT_SERIOUS"
L10_1[L11_1] = L12_1
L11_1 = "GROUND_ADMIN_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "m_Pos"
L12_1 = "C"
L10_1[L11_1] = L12_1
L11_1 = "그러다가 뜻밖의 증언으로 실마리가 풀린 거야."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ところが、思いがけない証言から糸口がつかめた。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Until one day, an unexpected testimony unraveled the whole case."
L10_1.m_Talk_ENG = L11_1
L11_1 = "後來是因為意料之外的證詞，使案情露出曙光。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "จนกระทั่งวันหนึ่ง คำให้การก็ได้คลี่คลายคดีทั้งหมด"
L10_1.m_Talk_THA = L11_1
L11_1 = "Cho đến một ngày, một lời khai bất ngờ đã làm sáng tỏ toàn bộ vụ án."
L10_1.m_Talk_VTN = L11_1
L11_1 = "后来，因为一个意料之外的证词找到了线索。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Bis eines Tages eine unerwartete Aussage den Fall aufklärte."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Jusqu'au jour où un témoignage inattendu a permis de démêler toute l'affaire."
L10_1.m_Talk_FRA = L11_1
