L14_1 = "CHARADE2_ACT1_PROLOGUE@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 5700101
L13_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "GROUND_ADMIN_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "바로 저 아이야, 루이즈 로랑생."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "それがあの子だ、ルイーズ・ローランサン。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "That's her. Louisé Laurencin."
L13_1.m_Talk_ENG = L14_1
L14_1 = "就是她，露易絲·羅蘭桑的證詞。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เธอก็คือ หลุยส์ ลอเรนซิน"
L13_1.m_Talk_THA = L14_1
L14_1 = "Đó là cô ấy. Louise Laurencin."
L13_1.m_Talk_VTN = L14_1
L14_1 = "就是那个孩子，路易斯·罗兰珊。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Es war die Aussage dieses Kindes. Louise Laurencin."
L13_1.m_Talk_DEU = L14_1
L14_1 = "C'était son témoignage à elle, Louise Laurencin."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "CHARADE2_ACT1_PROLOGUE@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 5700101
L14_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "GROUND_ADMIN_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "저 아이의 증언으로 아내 쪽의 외도 사실이 밝혀졌어."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "あの子の証言で、妻の方の浮気がバレた。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Her testimony revealed that her mother was having an affair."
L14_1.m_Talk_ENG = L15_1
L15_1 = "根據她的證詞，發現她媽媽有外遇。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "คำให้การของเธอบอกว่าแม่ของเธอมีชู้"
L14_1.m_Talk_THA = L15_1
L15_1 = "Lời khai của cô ấy đã tiết lộ người mẹ đã ngoại tình."
L14_1.m_Talk_VTN = L15_1
L15_1 = "正是那个孩子的证词，揭穿了她母亲怀有外遇的事实。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Durch ihre Aussage stellte sich heraus, dass ihre Mutter eine Affäre hatte."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Son témoignage a révélé que sa mère entretenait une liaison."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "CHARADE2_ACT1_PROLOGUE@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5700101
L15_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "GROUND_ADMIN_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "상대 남성은 북방합의체의 스파이였지. 처음부터 아티팩트를 노리고 접근했던 거야."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "相手の男性は北方合意体のスパイでな。最初からアーティファクトを狙って接近したわけだ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "The man was a Northern Union spy. He approached her with the intent of stealing the Artifact."
L15_1.m_Talk_ENG = L16_1
L16_1 = "而外遇對象就是北方和議會的間諜，男方從一開始就是為了人造神器才接近女方的。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ชายคนนั้นเป็นสายลับของสหภาพฝ่ายเหนือ เขาเข้าหาเธอด้วยความตั้งใจที่จะขโมยอาร์ติแฟ็กต์"
L15_1.m_Talk_THA = L16_1
L16_1 = "Người đàn ông đó là điệp viên của Liên Minh Phía Bắc. Anh ta tiếp cận cô với ý định đánh cắp Thần Khí."
L15_1.m_Talk_VTN = L16_1
L16_1 = "而对方正是北方联盟的间谍。从一开始，他就是为了人造神器才接近她母亲的。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Der Mann war ein Spion der Nordvereinigung. Er ging eine Beziehung mit ihr ein, um das Artefakt zu stehlen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "L'homme en question était un espion de l'Union du Nord. Il l'a approchée avec l'intention de voler l'artefact."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "CHARADE2_ACT1_PROLOGUE@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 5700101
L16_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "GROUND_ADMIN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "그 증언 이후에 유죄 판결이 확정되었고……."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "証言後に有罪判決が確定し……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "After Louisé's testimony, her mother was convicted..."
L16_1.m_Talk_ENG = L17_1
L17_1 = "有了她的證詞，她的父母最後被判處有罪……"
L16_1.m_Talk_TWN = L17_1
L17_1 = "หลังจากให้การเป็นพยานของ หลุยส์ แม่ของเธอจึงถูกตัดสินว่ามีความผิด..."
L16_1.m_Talk_THA = L17_1
L17_1 = "Sau lời khai của Louisé', người mẹ đã bị kết án..."
L16_1.m_Talk_VTN = L17_1
L17_1 = "在她作证之后，法庭做出了有罪判决……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Nach Louises Aussage wurde ihre Mutter verurteilt ..."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Après le témoignage de Louise, sa mère a été condamnée..."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "CHARADE2_ACT1_PROLOGUE@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5700101
L17_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "GROUND_ADMIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "로랑생 부부는 모두 형이 집행되기 전에 스스로 목숨을 끊었지."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ローランサン夫婦は二人とも、刑が執行される前に自殺したんだ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Both Mr. and Mrs. Laurencin, however, took their own lives before their sentence was executed."
L17_1.m_Talk_ENG = L18_1
L18_1 = "羅蘭桑夫婦則在入監前雙雙自殺死亡。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "อย่างไรก็ตาม ทั้งครอบครัวลอเรนซิน ต่างปลิดชีวิตตนเองก่อนที่จะได้รับโทษประหารชีวิต"
L17_1.m_Talk_THA = L18_1
L18_1 = "Tuy nhiên, cả ông và bà Laurencin đều tự kết liễu đời mình trước khi bản án được thi hành."
L17_1.m_Talk_VTN = L18_1
L18_1 = "然而罗兰珊夫妇却在执行判决前双双自杀了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Sowohl Herr als auch Frau Laurencin nahmen sich jedoch das Leben, bevor ihr Urteil vollstreckt werden konnte."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Mais monsieur et madame Laurencin se sont donnés la mort avant que leur peine ne soit appliquée."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
