L21_1 = "CHARADE2_ACT1_PROLOGUE@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5700101
L20_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "m_Action"
L22_1 = "SELECT"
L20_1[L21_1] = L22_1
L21_1 = "m_ActionStrKey"
L22_1 = "MARK5"
L20_1[L21_1] = L22_1
L21_1 = "아이의 증언만으로 내릴 판결은 아니군."
L20_1.m_Talk_KOREA = L21_1
L21_1 = "子どもの証言だけで下すような判決ではないな。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I don't think a child's testimony would have been enough for that sentence."
L20_1.m_Talk_ENG = L21_1
L21_1 = "怎麼可以光憑孩子的證詞就判有罪呢？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ผมไม่คิดว่าคำให้การของเด็กจะเพียงพอสำหรับสำนวนคดีนั้น"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tôi không nghĩ lời khai của một đứa trẻ đã đủ để kết án đó."
L20_1.m_Talk_VTN = L21_1
L21_1 = "只通过一个孩子的证词，还不足以做出判决吧？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ich glaube nicht, dass einzig und allein die Aussage eines Kindes für eine Verurteilung ausgereicht hätte."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Je ne pense pas que le témoignage d'un enfant suffise pour être condamné."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "CHARADE2_ACT1_PROLOGUE@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5700101
L21_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "m_Action"
L23_1 = "SELECT"
L21_1[L22_1] = L23_1
L22_1 = "m_ActionStrKey"
L23_1 = "MARK5"
L21_1[L22_1] = L23_1
L22_1 = "스파이라는 건 어떻게 알아낸 거지?"
L21_1.m_Talk_KOREA = L22_1
L22_1 = "スパイだということはどうしてわかったんだ？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "How did they figure out that the man was a spy?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "怎麼知道對方是間諜的？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "พวกเขารู้ได้ไงว่าชายคนนั้นเป็นสายลับ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Làm sao họ phát hiện ra người đàn ông đó là gián điệp?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "他们是怎么知道那个人是间谍的？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wie haben sie überhaupt herausgefunden, dass der Mann ein Spion war?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Comment ont-ils appris que l'homme était un espion ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "CHARADE2_ACT1_PROLOGUE@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5700101
L22_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "m_Face"
L24_1 = "UNIT_IDLE"
L22_1[L23_1] = L24_1
L23_1 = "m_Action"
L24_1 = "MARK"
L22_1[L23_1] = L24_1
L23_1 = "m_ActionStrKey"
L24_1 = "MARK5"
L22_1[L23_1] = L24_1
L23_1 = "GROUND_ADMIN_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "m_Pos"
L24_1 = "C"
L22_1[L23_1] = L24_1
L23_1 = "맞아. 재판에는 저 애 말고도 <color=#ffd34c>또 다른 증인</color>이 존재해."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ああ。実は、裁判にはあの子の以外にも<color=#ffd34c>もう一人の証人</color>が存在する。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "You're right. There was <color=#ffd34c>another witness</color> besides her."
L22_1.m_Talk_ENG = L23_1
L23_1 = "沒錯，所以除了她之外，還有<color=#ffd34c>另一個證人</color>。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ใช่ๆ แล้วก็มี<color=#ffd34c>พยานอีกคน</color>นอกจากเธอด้วย"
L22_1.m_Talk_THA = L23_1
L23_1 = "Đúng thế. Ngoài cô bé còn có <color=#ffd34c>một nhân chứng khác</color>."
L22_1.m_Talk_VTN = L23_1
L23_1 = "因为审判时除了那个孩子外，还存在<color=#ffd34c>另外一个证人</color>。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Du hast recht. Außer ihr gab es <color=#ffd34c>noch eine weitere Zeugin</color>."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Tu as raison. Il y avait <color=#ffd34c>un autre témoin</color> en plus d'elle."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "CHARADE2_ACT1_PROLOGUE@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 5700101
L23_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "GROUND_ADMIN_NULL_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "m_Pos"
L25_1 = "C"
L23_1[L24_1] = L25_1
L24_1 = "<color=#ffd34c>오지만디아스</color>. 당시에는 리그에서 주가를 올리던 루키였지."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "<color=#ffd34c>オジマンディアス</color>。当時のリーグで評判のルーキーだった。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "<color=#ffd34c>Ozymandias</color>. At the time, she was an up-and-coming rookie in the league."
L23_1.m_Talk_ENG = L24_1
L24_1 = "就是<color=#ffd34c>奧茲曼迪亞斯</color>，她當時是在聯賽中身價水漲船高的新人。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "นั่นคือ<color=#ffd34c>โอซีมานเดียส</color> ซึ่งในเวลานั้น เธอเป็นมือใหม่ที่กำลังมาแรงในลีก"
L23_1.m_Talk_THA = L24_1
L24_1 = "<color=#ffd34c>Ozymandias</color>. Vào thời điểm đó, cô ấy là một tân binh mới nổi của giải đấu."
L23_1.m_Talk_VTN = L24_1
L24_1 = "<color=#ffd34c>奥兹曼迪亚斯</color>。当时在联赛中，是备受瞩目的新秀。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "<color=#ffd34c>Ozymandias</color>. Sie war damals eine aufstrebende Spielerin in der Liga."
L23_1.m_Talk_DEU = L24_1
L24_1 = "<color=#ffd34c>Ozymandias</color>. À l'époque, elle était une recrue prometteuse de la Compétition."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "CHARADE2_ACT1_PROLOGUE@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 5700101
L24_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "GROUND_ADMIN_NULL_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "m_Pos"
L26_1 = "C"
L24_1[L25_1] = L26_1
L25_1 = "그 사건은 관리국에 굉장히 불명예스러운 일이야."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "あの事件は管理局にとっては非常に不名誉なものだ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "The Administration has been severely tarnished by this case."
L24_1.m_Talk_ENG = L25_1
L25_1 = "那件事對管理局而言不是一件光榮的事。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "แล้วฝ่ายบริหารก็ได้รับความเสียหายอย่างมากจากเธอในคดีนี้ด้วย"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cục Quản Lý đã bị hoen ố nghiêm trọng bởi trường hợp này."
L24_1.m_Talk_VTN = L25_1
L25_1 = "那件事对管理局来说是非常不光彩的。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Dieser Fall war eine große Schande für die Administration."
L24_1.m_Talk_DEU = L25_1
L25_1 = "L'Administration a été gravement ternie par cette affaire."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "CHARADE2_ACT1_PROLOGUE@175#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5700101
L25_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "GROUND_ADMIN_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "m_Pos"
L27_1 = "C"
L25_1[L26_1] = L27_1
L26_1 = "당신의 도움으로 저 아이가 세상에 알려지면, 그 사건도 다시 조명 받겠지."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "あなたの助けであの子が世間に知られるようになれば、あの事件もまた注目されるだろう。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "If word gets out that you're helping her, her case will also resurface."
L25_1.m_Talk_ENG = L26_1
L26_1 = "要是因為你的幫助使她聲名大噪，那件事一定會再次受到關注。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "หากมีข่าวว่าคุณกำลังช่วยเหลือเธอ คดีของเธอก็จะเกิดขึ้นอีกครั้งเช่นกัน"
L25_1.m_Talk_THA = L26_1
L26_1 = "Nếu có tin đồn ngài đang giúp đỡ cô bé thì vụ đó cũng sẽ lại nổi lên."
L25_1.m_Talk_VTN = L26_1
L26_1 = "如果那个孩子在你的帮助下被世人所知，相应的，那起案子也将会重新受到关注。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Wenn bekannt wird, dass du ihr hilfst, wird auch dieser Fall wieder ins Rampenlicht gerückt."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Si le mot sort que tu l'aides, cet incident refera également surface."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "CHARADE2_ACT1_PROLOGUE@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5700101
L26_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "m_Face"
L28_1 = "UNIT_PRIDE"
L26_1[L27_1] = L28_1
L27_1 = "GROUND_ADMIN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "m_Pos"
L28_1 = "C"
L26_1[L27_1] = L28_1
L27_1 = "내부에서는 벌써 얘기가 오가고 있어. 당신의 행동은 전부 정치적으로 해석될 수 있으니까."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "内部ではすでに話し合いが始まっている。あなたの行動は、すべて政治的に解釈される可能性があるからな。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "There are already talks from inside. Your actions can all be interpreted as having a political agenda."
L26_1.m_Talk_ENG = L27_1
L27_1 = "這件事已經在內部傳開來，你的一舉一動都會被解讀成帶有政治意涵的。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "มีการพูดจากวงใน ว่าการกระทำของคุณถือเป็นเรื่องของการเมือง"
L26_1.m_Talk_THA = L27_1
L27_1 = "Đã có những cuộc nói chuyện từ bên trong. Tất cả hành động của ngài đều có thể được hiểu là có mục đích chính trị."
L26_1.m_Talk_VTN = L27_1
L27_1 = "内部已经有所议论了，你的全部行为都有可能会被站在政治的角度去解读。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Es wird bereits innerhalb der Administration über dich gemunkelt. Deine Handlungen könnten alle als politisch motiviert interpretiert werden."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Les gens parlent de toi en interne. Tous tes gestes pourraient être interprétés comme suivant un agenda politique."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "CHARADE2_ACT1_PROLOGUE@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 5700101
L27_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "GROUND_ADMIN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "m_Pos"
L29_1 = "C"
L27_1[L28_1] = L29_1
L28_1 = "그러니 저 아이를 돕는 건 이쯤에서 그만둬."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "だからあの子を助けるのはこのくらいにしておけ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "So, I suggest you stop helping her."
L27_1.m_Talk_ENG = L28_1
L28_1 = "所以你還是收手吧。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ฉันแนะนำให้คุณหยุดช่วยเหลือสนับสนุนเธอซะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Vì vậy, tôi khuyên ngài nên ngừng giúp đỡ cô bé."
L27_1.m_Talk_VTN = L28_1
L28_1 = "所以，你对她们的帮助，还是到此为止吧。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Also schlage ich vor, dass du lieber aufhörst, diesem Kind zu helfen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Je te suggère donc d'arrêter de lui venir en aide."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "CHARADE2_ACT1_PROLOGUE@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 5700101
L28_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "m_Face"
L30_1 = "UNIT_SERIOUS"
L28_1[L29_1] = L30_1
L29_1 = "GROUND_ADMIN_NULL_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "m_Pos"
L30_1 = "C"
L28_1[L29_1] = L30_1
L29_1 = "m_Crash"
L28_1[L29_1] = 20
L29_1 = "애초에 당신 목적은 건틀렛 리그가 아니라 시니어들과의 협상이잖아?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "そもそもあなたの目的はガントレットリーグではなく、シニアとの交渉だろう？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I mean, your goal wasn't to enter the Gauntlet League but to negotiate with Seniors, right?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "你的目的不是聖鎧聯賽，而是和Senior談判不是嗎？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ฉันรู้ว่า เป้าหมายของคุณไม่ใช่การเข้าชิงลีกกอนต์เล็ต แต่เป็นการได้เข้าพบกับผู้อาวุโสใช่ไหม?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ý tôi là, mục tiêu của ngài đâu phải là tham gia Gauntlet League mà là đàm phán với Thành Viên Cấp Cao, phải không?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "从一开始你的目的就不是圣铠联赛，而是想和资深管理者协商对吧？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Du hattest doch von Anfang an nicht vor an der Fehde-Liga teilzunehmen, sondern Verhandlungen mit den Senioren zu führen, nicht wahr?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Après tout, ton objectif n'est pas d'entrer dans la Compétition mais de négocier avec les Seniors, non ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "CHARADE2_ACT1_PROLOGUE@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5700101
