L30_1 = "m_Face"
L31_1 = "UNIT_IDLE"
L29_1[L30_1] = L31_1
L30_1 = "GROUND_ADMIN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "m_Pos"
L31_1 = "C"
L29_1[L30_1] = L31_1
L30_1 = "리하르트가 내건 조건 때문이라면, 차라리 저 애들 말고 다른 선수를 영입해."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "リヒャルトが出した条件のためなら、あの子たちではなくて他の選手をスカウトするんだな。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "If it's because of Richard's terms, I strongly advise you to recruit someone else."
L29_1.m_Talk_ENG = L30_1
L30_1 = "理查提出的條件是改派其他選手參賽。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "หากเป็นเพราะเงื่อนไขของริชาร์ด ฉันแนะนำให้คุณรับสมัครคนอื่นมาแทนเธอซะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nếu đó là vì điều kiện của Richard, tôi thực sự khuyên ngài nên tuyển người khác."
L29_1.m_Talk_VTN = L30_1
L30_1 = "如果是因为理查德提出的条件，那我强烈建议你聘请其他选手。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Wenn es an Richards Bedingungen liegt, rate ich dir dringend, andere Spieler als diese Kinder zu rekrutieren."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Si c'est à cause des conditions de Richard, je te conseille fortement de recruter quelqu'un d'autre."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
