L30_1[L31_1] = L32_1
L31_1 = "자네가 그렇게까지 날 걱정해줄 줄은 몰랐는데?"
L30_1.m_Talk_KOREA = L31_1
L31_1 = "君がそこまで私のことを心配してくれるとは、意外だな。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I didn't think you'd be so worried about me."
L30_1.m_Talk_ENG = L31_1
L31_1 = "沒想到你這麼擔心我？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผมไม่คิดว่าคุณจะเป็นห่วงผมขนาดนี้"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi không nghĩ cô lại lo lắng cho tôi đến thế."
L30_1.m_Talk_VTN = L31_1
L31_1 = "呵呵，没想到你会这么为我担心？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich hätte nicht gedacht, dass du dir solche Sorgen um mich machen würdest."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je ne pensais pas que tu t'inquiéterais autant pour moi."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
