L31_1[L32_1] = L33_1
L32_1 = "미안하지만, 한 번 고용한 직원들을 버리진 않아."
L31_1.m_Talk_KOREA = L32_1
L32_1 = "すまないが、一度雇った社員を切り捨てたりはしない主義なんだ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I'm sorry, but I don't abandon the people I hire."
L31_1.m_Talk_ENG = L32_1
L32_1 = "很抱歉，我是不會拋棄我的員工的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ผมขอโทษ แต่ผมจะไม่ละทิ้งคนของผม "
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi xin lỗi, nhưng tôi không bỏ rơi những người tôi tuyển đâu."
L31_1.m_Talk_VTN = L32_1
L32_1 = "很抱歉，我是不会抛弃已经雇佣的职员的。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Tut mir ja leid, aber ich kann meinen Angestellten nicht so einfach im Stich lassen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je suis navré, mais je ne suis pas du genre à abandonner les gens que j'embauche."
