L36_1 = "USER_ADMIN_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "부모가 죄를 저질렀다고 해도, 그게 아이를 외면할 이유는 될 수 없어."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "親が罪を犯したとしても、それが子どもから目を背ける理由にはならないさ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Whatever sin her parents committed doesn't justify my neglecting her."
L35_1.m_Talk_ENG = L36_1
L36_1 = "就算她的父母親犯罪，但那不足以構成我棄她於不顧的理由。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ถึงพ่อแม่ของเธอทำไม่ดีลงไป  ผมก็ไม่คิดจะตัดเธอออกไป"
L35_1.m_Talk_THA = L36_1
L36_1 = "Dù cha mẹ cô bé phạm tội gì cũng không biện minh được cho việc tôi bỏ rơi cô bé."
L35_1.m_Talk_VTN = L36_1
L36_1 = "就算父母有罪，那也不能成为冷落孩子的理由。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Auch wenn ihre Eltern eine Straftat begangen haben, rechtfertigt das keineswegs, sich von diesem Mädchen abzuwenden."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Quel que soit les crimes que ses parents ont commis, ça ne justifie pas que je la laisse tomber."
L35_1.m_Talk_FRA = L36_1
