L37_1 = "*Sigh...* Fine, do whatever you want."
L36_1.m_Talk_ENG = L37_1
L37_1 = "哀……隨便你吧。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "*ถอนหายใจ...* ก็ได้ ทำสิ่งที่คุณต้องการไปเลย"
L36_1.m_Talk_THA = L37_1
L37_1 = "*Thở dài...* Được rồi, ngài muốn sao cũng được."
L36_1.m_Talk_VTN = L37_1
L37_1 = "呵……随你便吧。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "*Seufz* Mach doch, was du willst."
L36_1.m_Talk_DEU = L37_1
L37_1 = "*Soupir* Très bien, fais comme tu veux."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "CHARADE2_ACT1_PROLOGUE@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5700101
L37_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "m_Face"
L39_1 = "UNIT_IDLE"
L37_1[L38_1] = L39_1
L38_1 = "GROUND_ADMIN_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "m_Pos"
L39_1 = "C"
L37_1[L38_1] = L39_1
L38_1 = "하지만 조심하는 게 좋을 거야. 여기 리그는 경기 결과 보다 스폰서들 입김이 더 중요하거든."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "だが、気をつけた方がいい。ここのリーグは試合の勝ち負けより、スポンサーの影響力を重視する。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "But you'd better be careful. The league is more influenced by its sponsors than the outcome of the matches."
L37_1.m_Talk_ENG = L38_1
L38_1 = "但我勸你小心一點，在這裡，影響聯賽結果的關鍵是贊助商。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แต่คุณควรระวังตัวไว้ เพราะลีกนี้มีผู้สนับสนุนจากผู้มีอิทธิพลที่ไม่หวังผลการแข่งขัน"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nhưng tốt nhất nên cẩn thận. Giải đấu bị ảnh hưởng nhiều bởi các nhà tài trợ hơn là kết quả trận đấu."
L37_1.m_Talk_VTN = L38_1
L38_1 = "但还是小心点。这里的联赛，赞助商的一句话比结果更重要。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Aber du solltest lieber vorsichtig sein. In dieser Liga ist der Einfluss der Sponsoren wichtiger als die Ergebnisse der Spiele."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Mais tu ferais mieux de faire attention. Lors de la Compétition, l'influence des sponsors est plus importante que les résultats des matchs."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "CHARADE2_ACT1_PROLOGUE@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5700101
L38_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "GROUND_ADMIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "m_Pos"
L40_1 = "C"
L38_1[L39_1] = L40_1
L39_1 = "그것들에게 갑자기 나타나서 본선에 진출한 당신 회사는, 눈엣가시나 마찬가지야."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "いきなり現れて本戦に進出したあなたの会社は、彼らにとっては目障りな存在以外の何者でもない。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "So, for your company to suddenly advance into elimination rounds will be a nuisance to them."
L38_1.m_Talk_ENG = L39_1
L39_1 = "你公司突然冒出來參加決賽，他們一定會視你為眼中釘的。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ดังนั้น การที่ทีมของคุณผ่านเข้าสู่รอบคัดเลือกกะทันหันจะสร้างความรำคาญให้กับพวกเขาได้"
L38_1.m_Talk_THA = L39_1
L39_1 = "Nên việc công ty của ngài đột ngột tiến vào vòng trong sẽ gây phiền toái cho họ."
L38_1.m_Talk_VTN = L39_1
L39_1 = "对他们来说，突然出现并进入了淘汰赛的你们，简直就和眼中钉一样。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Wenn es dein Unternehmen also plötzlich bis in die Hauptrunde schaffen sollte, wird es den Sponsoren ein Dorn im Auge sein."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Alors si ton entreprise arrive soudainement jusqu'aux éliminatoires, ça pourrait être une épine dans le pied pour eux."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "CHARADE2_ACT1_PROLOGUE@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 5700101
L39_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "m_Face"
L41_1 = "UNIT_SERIOUS"
L39_1[L40_1] = L41_1
L40_1 = "GROUND_ADMIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "m_Pos"
L41_1 = "C"
L39_1[L40_1] = L41_1
L40_1 = "그러니 더 이상 <color=#ffd34c>정정당당</color>하게 싸워주진 않을 거라고."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "この先は<color=#ffd34c>正々堂々</color>と戦ってはくれないはずだ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "In other words, they won't be fighting you <color=#ffd34c>fair and square</color>."
L39_1.m_Talk_ENG = L40_1
L40_1 = "而且他們一定不會使用<color=#ffd34c>正當手段</color>。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "พูดอีกอย่าง พวกเขาจะไม่ต่อสู้กับคุณ<color=#ffd34c>อย่างยุติธรรมและจะต้องมีเล่ห์เหลี่ยมกับพวกคุณแน่</color>"
L39_1.m_Talk_THA = L40_1
L40_1 = "Nói cách khác, họ sẽ không đấu với ngài một cách <color=#ffd34c>công bằng và chính trực</color> đâu."
L39_1.m_Talk_VTN = L40_1
L40_1 = "所以他们是不会再<color=#ffd34c>堂堂正正</color>地和你一决高下的。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Mit anderen Worten, sie werden nicht <color=#ffd34c>fair</color> kämpfen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "En d'autres termes, ils ne se battent pas <color=#ffd34c>à la loyale</color>."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
