L42_1 = "CHARADE2_ACT1_PROLOGUE@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 5700101
L41_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "USER_ADMIN_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "부정행위에 조치를 취할 생각은 없나 보군."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "不正行為に対して措置を取る気はないようだな。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I assume you don't plan on taking action for the malfeasance."
L41_1.m_Talk_ENG = L42_1
L42_1 = "看來你無意採取措施打擊作弊行為呢。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ผมหวังว่าคุณไม่ได้มีส่วนวางแผนที่จะดำเนินการกระทำพวกนั้นนะ "
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi cho rằng ngài không có ý định hành động trước sự sai trái."
L41_1.m_Talk_VTN = L42_1
L42_1 = "看来你无意采取措施打击作弊行为呢。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich gehe davon aus, dass Sie nicht vorhaben, wegen des Fehlverhaltens Maßnahmen zu ergreifen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je suppose que tu n'as pas l'intention de prendre des mesures contre les tricheries."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "CHARADE2_ACT1_PROLOGUE@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5700101
L42_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "CHARADE_ADMIN_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "예. 지배층의 불문율을 존중하기 때문이기도 하지만……."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "はい。支配階級の不文律を尊重しているためでもありますが……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I'm afraid not. Primarily because I respect the unwritten law of the ruling class..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "是的，部分原因是出於尊重高層的淺規則。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ผมเกรงว่าจะไม่ ตามหลักของผม ผมเคารพกฎหมายที่ไม่ได้เขียนไว้ในกฎหมายเท่านั้น..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi e là không. Chủ yếu là vì tôi tôn trọng luật bất thành văn của giai cấp thống trị..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "是的，因为我也会尊重统治阶层所默认的规定。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "So ist es. Vor allem, weil ich das ungeschriebene Gesetz der herrschenden Klasse respektiere ..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "J'ai bien peur que non. Principalement parce que je respecte la loi non-écrite de la classe dirigeante..."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "CHARADE2_ACT1_PROLOGUE@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 5700101
L43_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "CHARADE_ADMIN_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "무엇보다도 당신의 능력을 증명하기에 이번 리그가 좋은 기회라고 판단했습니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "何よりもあなたの能力を証明するのに、今度のリーグがいい機会であると判断しました。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "But moreover, I consider this League to be a good opportunity for you to prove your abilities."
L43_1.m_Talk_ENG = L44_1
L44_1 = "最重要的是，我認為這次聯賽是證明您能力的好機會。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แต่ยิ่งกว่านั้น ผมถือว่าลีกนี้เป็นโอกาสที่ดีสำหรับคุณในการพิสูจน์ความสามารถของคุณด้วย"
L43_1.m_Talk_THA = L44_1
L44_1 = "Nhưng hơn thế nữa, tôi coi Giải đấu này là cơ hội tốt để ngài chứng tỏ khả năng của mình."
L43_1.m_Talk_VTN = L44_1
L44_1 = "最重要的是，我认为这次联赛是证明您能力的好机会。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Aber darüber hinaus halte ich diese Liga für eine gute Gelegenheit für Sie, Ihre Fähigkeiten unter Beweis zu stellen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Mais de plus, je considère cette Compétition comme une bonne occasion de prouver tes capacités."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
