L46_1 = "m_ActionStrKey"
L47_1 = "MARK8"
L45_1[L46_1] = L47_1
L46_1 = "그런 부조리한 승부가 내 전문 분야라네."
L45_1.m_Talk_KOREA = L46_1
L46_1 = "そのような不条理な勝負が私の専門分野だ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Well, unjust games are my specialty."
L45_1.m_Talk_ENG = L46_1
L46_1 = "在比賽中來陰的我最會。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เกมที่ไม่ยุติธรรมเป็นสิ่งพิเศษสำหรับผม"
L45_1.m_Talk_THA = L46_1
L46_1 = "Chà, những trò chơi bất công là sở trường của tôi."
L45_1.m_Talk_VTN = L46_1
L46_1 = "正巧，那种不合理的胜负正是我的专业领域。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Nun, unfaire Spiele sind meine Spezialität."
L45_1.m_Talk_DEU = L46_1
L46_1 = "La concurrence déloyale, c'est ma spécialité."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "CHARADE2_ACT1_PROLOGUE@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5700101
L46_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "m_Action"
L48_1 = "SELECT"
L46_1[L47_1] = L48_1
L47_1 = "m_ActionStrKey"
L48_1 = "MARK9"
L46_1[L47_1] = L48_1
L47_1 = "정정당당하게 싸우는 상대가 세상에 어디 있나?"
L46_1.m_Talk_KOREA = L47_1
L47_1 = "正々堂々と戦う相手など、この世にいないだろう？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Since when did anyone fight fair and square?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "現在還有誰會在比賽中使用正當手段嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ตั้งแต่ต้นมีใครกันที่ต่อสู้อย่างยุติธรรมและความยุติธรรมเกิดขึ้นตั้งแต่เมื่อไหร่?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Từ khi nào mà có người đấu một cách công bằng và chính trực vậy?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "这世上哪有会堂堂正正一决高下的对手呢？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Gibt es überhaupt jemanden auf dieser Welt, der fair kämpft?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Après tout, qui dans ce monde se bat à la loyale ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
