L49_1 = "m_Crash"
L48_1[L49_1] = 10
L49_1 = "그렇게까지 말한다면, 나도 더 이상 말리진 않겠어."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そこまで言うなら、私ももう止めない。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "If you want to go the hard way, then I won't stop you."
L48_1.m_Talk_ENG = L49_1
L49_1 = "既然如此，我也不會再說什麼。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ถ้าอยากไปแบบยากหน่อย ฉันก็จะไม่ห้ามคุณ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nếu ngài muốn đi con đường khó khăn, thì tôi sẽ không ngăn cản."
L48_1.m_Talk_VTN = L49_1
L49_1 = "既然你都这么说了，那我也不会再劝你了。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wenn du die harte Tour bevorzugst, werde ich dich bestimmt nicht aufhalten."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Si tu veux jouer les durs, vas-y. Je ne te retiendrai pas."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "CHARADE2_ACT1_PROLOGUE@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
