L50_1 = "m_Face"
L51_1 = "UNIT_PRIDE"
L49_1[L50_1] = L51_1
L50_1 = "GROUND_ADMIN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "m_Pos"
L51_1 = "C"
L49_1[L50_1] = L51_1
L50_1 = "마음대로 해. 응원은 해주지."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "勝手にしろ。応援だけはしてやる。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Do what you want. I'll be rooting for you."
L49_1.m_Talk_ENG = L50_1
L50_1 = "你開心就好，加油。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "นั้นคือสิ่งที่คุณเลือก ฉันจะเป็นกำลังใจให้คุณล่ะกัน"
L49_1.m_Talk_THA = L50_1
L50_1 = "Hãy làm những gì ngài muốn. Tôi sẽ cổ vũ cho ngài."
L49_1.m_Talk_VTN = L50_1
L50_1 = "你随意吧，我会为你加油的。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Mach, was du willst. Ich werde dich anfeuern."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Fais ce que tu veux. Je serai là pour t'encourager."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "CHARADE2_ACT1_PROLOGUE@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5700101
L50_1.m_CutScenStrID = "CHARADE2_ACT1_PROLOGUE"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "GROUND_ADMIN_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "m_Pos"
L52_1 = "C"
L50_1[L51_1] = L52_1
L51_1 = "성패와 별개로, 당신이 이런데서 져 버리면 우리 체면도 좀 그렇잖아?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "勝敗を抜きにしても、あなたがこんなところで負けてしまうと私たちの面子も立たないからな？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Regardless of the outcome, it won't look good for any of us if you lose, right?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "不過先不說勝負，你要是在這種地方輸掉，我們的面子也掛不住，你知道吧？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ไม่ว่าผลลัพธ์จะเป็นเช่นไร มันก็จะไม่ดีสำหรับพวกเราคนใดคนหนึ่งถ้าคุณแพ้ว่าไหม?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Dù kết quả thế nào, sẽ không tốt cho bất kỳ ai trong chúng ta nếu ngài thua, phải không?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "这与胜负无关，毕竟要是你输了，我们的面子也没地方搁啊。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Unabhängig vom Ergebnis wird es uns nicht gut dastehen lassen, wenn du verlierst, oder?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Quel que soit le résultat, si tu perds la Compétition, ça ne sera pas bon pour notre image à tous."
L50_1.m_Talk_FRA = L51_1
